SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
START TRANSACTION;
SET time_zone = "+00:00";

CREATE TABLE `treinamentos_slides` (
  `id` int UNSIGNED NOT NULL,
  `apresentacao_id` int UNSIGNED NOT NULL,
  `ordem` int UNSIGNED NOT NULL DEFAULT '1',
  `titulo` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Novo slide',
  `transicao` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'fade',
  `layout` enum('esquerda','centro','dividido','cheio') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'esquerda',
  `fundo_tipo` enum('tema','solido','gradiente','imagem') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'tema',
  `fundo_cor` varchar(9) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fundo_cor2` varchar(9) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fundo_angulo` smallint NOT NULL DEFAULT '160',
  `fundo_imagem` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fundo_escurecer` tinyint UNSIGNED NOT NULL DEFAULT '0',
  `cor_texto` varchar(9) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `instrutor_visivel` tinyint(1) NOT NULL DEFAULT '1',
  `instrutor_posicao` enum('direita','esquerda','centro','centro-esquerda','centro-direita') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'direita',
  `instrutor_lado_conteudo` enum('auto','esquerda','direita','centro') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'auto',
  `instrutor_giro` enum('herdar','nenhum','leve','moderado','tresquartos','perfil') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'herdar',
  `instrutor_escala` decimal(3,2) NOT NULL DEFAULT '1.00',
  `instrutor_camera` enum('herdar','full','mid','upper','head','joelhos','busto') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'herdar',
  `conteudo_html` longtext COLLATE utf8mb4_unicode_ci,
  `resumo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `criado_em` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `atualizado_em` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `exigencia` enum('herdar','nenhuma','quiz','todas') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'herdar'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `treinamentos_slides` (`id`, `apresentacao_id`, `ordem`, `titulo`, `transicao`, `layout`, `fundo_tipo`, `fundo_cor`, `fundo_cor2`, `fundo_angulo`, `fundo_imagem`, `fundo_escurecer`, `cor_texto`, `instrutor_visivel`, `instrutor_posicao`, `instrutor_lado_conteudo`, `instrutor_giro`, `instrutor_escala`, `instrutor_camera`, `conteudo_html`, `resumo`, `criado_em`, `atualizado_em`, `exigencia`) VALUES
(375, 29, 1, 'Introdução', 'fade', 'esquerda', 'gradiente', '#08243F', '#134E86', 160, NULL, 0, '#FFFFFF', 1, 'direita', 'auto', 'herdar', 1.00, 'head', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":11,\"w\":58,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Programa de Segurança do Trabalho<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":17.2,\"w\":70,\"h\":10.5,\"html\":\"<h2>Equipamento de Proteção Individual (NR-6)<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":29.9,\"w\":58,\"h\":9.9,\"html\":\"<p>Capacitação obrigatória prevista na Norma Regulamentadora número 6 e nos artigos 157, 158 e 166 da Consolidação das Leis do Trabalho.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":125,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"texto\",\"x\":4,\"y\":42,\"w\":58,\"h\":19.8,\"html\":\"<p><strong>O que este treinamento cobre.<\\/strong> O conceito normativo de EPI e o que fica fora dele. A certificação, o fornecimento gratuito e o registro de entrega. Cada família de equipamento adotada na empresa, com uso correto, higienização e guarda. Os deveres do trabalhador, os deveres do empregador e o que fazer quando o equipamento deixa de proteger.<\\/p>\",\"oculto\":true},{\"z\":1,\"s\":{\"fs\":115,\"anim\":\"subir\"},\"id\":\"e5\",\"t\":\"texto\",\"x\":4,\"y\":67,\"w\":58,\"h\":16.2,\"html\":\"<ul><li>Quatro módulos, com quatro verificações de aprendizagem ao longo do caminho.<\\/li><li>Em vários momentos o conteúdo aguarda a sua ação na tela.<\\/li><li>Avaliação final com 10 questões sorteadas, 70% de aproveitamento e até 3 tentativas.<\\/li><li>Certificado de conclusão do treinamento.<\\/li><\\/ul>\",\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:11%;width:58%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Programa de Segurança do Trabalho</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:17.2%;width:70%;height:10.5%;z-index:1;--trc-fs:1.46;\"><h2>Equipamento de Proteção Individual (NR-6)</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:29.9%;width:58%;height:9.9%;z-index:1;\"><p>Capacitação obrigatória prevista na Norma Regulamentadora número 6 e nos artigos 157, 158 e 166 da Consolidação das Leis do Trabalho.</p></div>\n<div class=\"trc-el trc-texto nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:42%;width:58%;height:19.8%;z-index:1;--trc-fs:1.25;\"><p><strong>O que este treinamento cobre.</strong> O conceito normativo de EPI e o que fica fora dele. A certificação, o fornecimento gratuito e o registro de entrega. Cada família de equipamento adotada na empresa, com uso correto, higienização e guarda. Os deveres do trabalhador, os deveres do empregador e o que fazer quando o equipamento deixa de proteger.</p></div>\n<div class=\"trc-el trc-texto nv-oculto trv-anim-subir\" id=\"e5\" style=\"left:4%;top:67%;width:58%;height:16.2%;z-index:1;--trc-fs:1.15;\"><ul><li>Quatro módulos, com quatro verificações de aprendizagem ao longo do caminho.</li><li>Em vários momentos o conteúdo aguarda a sua ação na tela.</li><li>Avaliação final com 10 questões sorteadas, 70% de aproveitamento e até 3 tentativas.</li><li>Certificado de conclusão do treinamento.</li></ul></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-04 14:15:13', 'nenhuma'),
(376, 29, 2, 'Módulo 01', 'cima', 'esquerda', 'gradiente', '#08243F', '#134E86', 160, NULL, 0, '#FFFFFF', 1, 'direita', 'auto', 'herdar', 1.00, 'upper', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":144,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":33,\"w\":58,\"h\":6,\"html\":\"<div class=\\\"trc-eyebrow\\\" style=\\\"color:#7FC4FF\\\">Módulo 01<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":180,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":41.2,\"w\":58,\"h\":13,\"html\":\"<h2>Conceito e posição do EPI<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":104,\"anim\":\"subir\"},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":56.4,\"w\":58,\"h\":10.3,\"html\":\"<p>O que a norma define como equipamento de proteção individual, o que fica de fora e por que ele é a última medida da sequência de controle.<\\/p>\",\"oculto\":true}]}</script>\r\n<div class=\"trc-palco\">\r\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:33%;width:58%;height:6%;z-index:1;--trc-fs:1.44;\"><div class=\"trc-eyebrow\" style=\"color:#7FC4FF\">Módulo 01</div></div>\r\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:41.2%;width:58%;height:13%;z-index:1;--trc-fs:1.8;\"><h2>Conceito e posição do EPI</h2></div>\r\n<div class=\"trc-el trc-texto nv-oculto trv-anim-subir\" id=\"e3\" style=\"left:4%;top:56.4%;width:58%;height:10.3%;z-index:1;--trc-fs:1.04;\"><p>O que a norma define como equipamento de proteção individual, o que fica de fora e por que ele é a última medida da sequência de controle.</p></div>\r\n</div>', NULL, '2026-08-31 07:33:43', '2026-09-09 15:38:50', 'nenhuma'),
(377, 29, 4, 'O que caracteriza um EPI', 'esquerda', 'esquerda', 'tema', '#FFFFFF', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'mid', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":58,\"h\":3.9,\"html\":\"<div class=\\\"trc-eyebrow\\\">Definição normativa<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":13,\"w\":58,\"h\":10.1,\"html\":\"<h2>O que caracteriza um EPI<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":25.2,\"w\":63.5,\"h\":12.7,\"html\":\"<p>A norma define EPI como todo dispositivo ou produto de uso individual utilizado pelo trabalhador e destinado à proteção contra riscos capazes de ameaçar a sua segurança e a sua saúde. Três elementos precisam estar presentes ao mesmo tempo.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":125,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"abas\",\"dados\":{\"itens\":[{\"t\":\"Uso individual\",\"f\":2,\"d\":\"O equipamento é dimensionado e entregue para uma única pessoa, que passa a responder pela guarda dele. O compartilhamento compromete três coisas ao mesmo tempo: o ajuste, porque cada corpo tem uma medida; a higiene, porque protetor auricular, respirador e luva ficam em contato direto com a pele; e a rastreabilidade, porque o registro deixa de refletir quem está de posse de cada item.\"},{\"t\":\"Finalidade de proteção\",\"f\":3,\"d\":\"A destinação principal do produto precisa ser proteger quem o utiliza contra um agente capaz de causar lesão ou doença. Itens que existem para conforto térmico, para padronização visual ou para identificação da equipe cumprem outra função, ainda que sejam obrigatórios por outro motivo dentro da empresa.\"},{\"t\":\"Risco identificado\",\"f\":4,\"d\":\"O agente precisa constar do levantamento de riscos da atividade. É esse levantamento que determina qual equipamento a tarefa exige, qual certificação ele deve ter e com que frequência será substituído. A escolha não parte do catálogo do fornecedor, do preço nem da preferência de quem executa.\"}],\"guiado\":true},\"x\":4,\"y\":32,\"w\":63,\"h\":40,\"oculto\":true},{\"z\":1,\"s\":{\"fs\":110,\"anim\":\"subir\"},\"id\":\"e5\",\"t\":\"bloco\",\"bloco\":\"alerta\",\"dados\":{\"tipo\":\"dica\",\"titulo\":\"O teste de enquadramento\",\"texto\":\"Protege quem está utilizando, foi entregue a uma pessoa determinada e o risco consta do levantamento da atividade? Respondendo sim às três perguntas, o item é EPI e segue todas as regras da norma.\"},\"x\":4,\"y\":76.6,\"w\":63,\"h\":16.4,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:58%;height:3.9%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Definição normativa</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:13%;width:58%;height:10.1%;z-index:1;--trc-fs:1.46;\"><h2>O que caracteriza um EPI</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:25.2%;width:63.5%;height:12.7%;z-index:1;\"><p>A norma define EPI como todo dispositivo ou produto de uso individual utilizado pelo trabalhador e destinado à proteção contra riscos capazes de ameaçar a sua segurança e a sua saúde. Três elementos precisam estar presentes ao mesmo tempo.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:32%;width:63%;height:40%;z-index:1;--trc-fs:1.25;\"><div class=\"trb trb-abas trb-guiado\" data-bloco=\"abas\" data-guiado=\"1\" data-apos=\"2\"><div class=\"trb-abas-barra\"><button type=\"button\" class=\"trb-aba\" data-i=\"0\" data-gi=\"0\" data-gf=\"2\">Uso individual</button><button type=\"button\" class=\"trb-aba\" data-i=\"1\" data-gi=\"1\" data-gf=\"3\">Finalidade de proteção</button><button type=\"button\" class=\"trb-aba\" data-i=\"2\" data-gi=\"2\" data-gf=\"4\">Risco identificado</button></div><div class=\"trb-abas-corpo\"><div class=\"trb-aba-painel\" data-i=\"0\">O equipamento é dimensionado e entregue para uma única pessoa, que passa a responder pela guarda dele. O compartilhamento compromete três coisas ao mesmo tempo: o ajuste, porque cada corpo tem uma medida; a higiene, porque protetor auricular, respirador e luva ficam em contato direto com a pele; e a rastreabilidade, porque o registro deixa de refletir quem está de posse de cada item.</div><div class=\"trb-aba-painel\" data-i=\"1\">A destinação principal do produto precisa ser proteger quem o utiliza contra um agente capaz de causar lesão ou doença. Itens que existem para conforto térmico, para padronização visual ou para identificação da equipe cumprem outra função, ainda que sejam obrigatórios por outro motivo dentro da empresa.</div><div class=\"trb-aba-painel\" data-i=\"2\">O agente precisa constar do levantamento de riscos da atividade. É esse levantamento que determina qual equipamento a tarefa exige, qual certificação ele deve ter e com que frequência será substituído. A escolha não parte do catálogo do fornecedor, do preço nem da preferência de quem executa.</div><div class=\"trb-aba-vazio\">Abra as abas na ordem pedida pelo instrutor.</div></div></div></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e5\" style=\"left:4%;top:76.6%;width:63%;height:16.4%;z-index:1;--trc-fs:1.1;\"><div class=\"trb trb-alerta trb-alerta-dica\" data-bloco=\"alerta\"><i class=\"bi bi-lightbulb\"></i><div><b>O teste de enquadramento</b><p>Protege quem está utilizando, foi entregue a uma pessoa determinada e o risco consta do levantamento da atividade? Respondendo sim às três perguntas, o item é EPI e segue todas as regras da norma.</p></div></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-04 14:44:24', 'herdar'),
(378, 29, 5, 'O que é e o que não é', 'esquerda', 'cheio', 'solido', '#F2F5F9', '#F3F6FA', 160, NULL, 0, NULL, 0, 'direita', 'auto', 'herdar', 1.00, 'herdar', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":92,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Delimitação do conceito<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":13.2,\"w\":92,\"h\":10.5,\"html\":\"<h2>O que é e o que não é<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":25.9,\"w\":92,\"h\":9.9,\"html\":\"<p>A coluna da direita reúne itens legítimos e muitas vezes obrigatórios, que apenas não se enquadram como EPI. A distinção importa porque define quem paga, quem substitui, o que precisa de certificado e o que precisa de registro de entrega.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":135,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"comparativo\",\"dados\":{\"aTitulo\":\"Enquadra-se como EPI\",\"aItens\":[{\"t\":\"Creme protetor com registro e CA\"},{\"t\":\"Luva selecionada pelo agente da tarefa\"},{\"t\":\"Calçado de segurança certificado\"},{\"t\":\"Protetor auricular de inserção ou concha\"},{\"t\":\"Óculos de segurança e protetor facial\"},{\"t\":\"Respirador com filtro adequado ao contaminante\"}],\"bTitulo\":\"Não se enquadra\",\"bItens\":[{\"t\":\"Uniforme, camisa e calça de trabalho\"},{\"t\":\"Crachá e colete de identificação\"},{\"t\":\"Luva de pano ou malha de uso doméstico\"},{\"t\":\"Creme hidratante e cosmético de farmácia\"},{\"t\":\"Óculos de grau sem certificação\"},{\"t\":\"Proteção fixa de máquina e guarda-corpo\"}]},\"x\":4,\"y\":38,\"w\":92,\"h\":36.7,\"oculto\":true},{\"z\":1,\"s\":{\"fs\":115,\"anim\":\"subir\"},\"id\":\"e5\",\"t\":\"bloco\",\"bloco\":\"alerta\",\"dados\":{\"tipo\":\"atencao\",\"titulo\":\"Proteção coletiva não é EPI\",\"texto\":\"Proteção fixa de máquina e guarda-corpo são medidas de proteção coletiva. Elas protegem todos que circulam na área, independem do comportamento individual e, por isso mesmo, vêm antes do EPI na sequência de controle. Nunca são substituídas por ele.\"},\"x\":4,\"y\":77,\"w\":92,\"h\":13.9,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:92%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Delimitação do conceito</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:13.2%;width:92%;height:10.5%;z-index:1;--trc-fs:1.46;\"><h2>O que é e o que não é</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:25.9%;width:92%;height:9.9%;z-index:1;\"><p>A coluna da direita reúne itens legítimos e muitas vezes obrigatórios, que apenas não se enquadram como EPI. A distinção importa porque define quem paga, quem substitui, o que precisa de certificado e o que precisa de registro de entrega.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:38%;width:92%;height:36.7%;z-index:1;--trc-fs:1.35;\"><div class=\"trb trb-comparativo\" data-bloco=\"comparativo\"><div class=\"trb-comp-col trb-comp-ok\"><div class=\"trb-comp-head\"><i class=\"bi bi-hand-thumbs-up\"></i>Enquadra-se como EPI</div><ul><li><i class=\"bi bi-check-lg\"></i><span>Creme protetor com registro e CA</span></li><li><i class=\"bi bi-check-lg\"></i><span>Luva selecionada pelo agente da tarefa</span></li><li><i class=\"bi bi-check-lg\"></i><span>Calçado de segurança certificado</span></li><li><i class=\"bi bi-check-lg\"></i><span>Protetor auricular de inserção ou concha</span></li><li><i class=\"bi bi-check-lg\"></i><span>Óculos de segurança e protetor facial</span></li><li><i class=\"bi bi-check-lg\"></i><span>Respirador com filtro adequado ao contaminante</span></li></ul></div><div class=\"trb-comp-col trb-comp-nao\"><div class=\"trb-comp-head\"><i class=\"bi bi-hand-thumbs-down\"></i>Não se enquadra</div><ul><li><i class=\"bi bi-x-lg\"></i><span>Uniforme, camisa e calça de trabalho</span></li><li><i class=\"bi bi-x-lg\"></i><span>Crachá e colete de identificação</span></li><li><i class=\"bi bi-x-lg\"></i><span>Luva de pano ou malha de uso doméstico</span></li><li><i class=\"bi bi-x-lg\"></i><span>Creme hidratante e cosmético de farmácia</span></li><li><i class=\"bi bi-x-lg\"></i><span>Óculos de grau sem certificação</span></li><li><i class=\"bi bi-x-lg\"></i><span>Proteção fixa de máquina e guarda-corpo</span></li></ul></div></div></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e5\" style=\"left:4%;top:77%;width:92%;height:13.9%;z-index:1;--trc-fs:1.15;\"><div class=\"trb trb-alerta trb-alerta-atencao\" data-bloco=\"alerta\"><i class=\"bi bi-exclamation-triangle\"></i><div><b>Proteção coletiva não é EPI</b><p>Proteção fixa de máquina e guarda-corpo são medidas de proteção coletiva. Elas protegem todos que circulam na área, independem do comportamento individual e, por isso mesmo, vêm antes do EPI na sequência de controle. Nunca são substituídas por ele.</p></div></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-04 14:44:24', 'herdar'),
(379, 29, 6, 'A sequência das medidas de controle', 'esquerda', 'esquerda', 'tema', '#FFFFFF', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'mid', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":58,\"h\":2.2,\"html\":\"<div class=\\\"trc-eyebrow\\\">Gerenciamento de riscos<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":10.4,\"w\":58,\"h\":5.9,\"html\":\"<h2>A sequência das medidas de controle<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":17.6,\"w\":58,\"h\":5.5,\"html\":\"<p>A norma não deixa a escolha livre. As medidas são avaliadas em ordem, e só se passa para a seguinte quando a anterior for tecnicamente inviável ou insuficiente.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":95,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"passos\",\"dados\":{\"itens\":[{\"t\":\"Eliminação do risco\",\"f\":\"1\",\"d\":\"Suprimir o agente ou a etapa que o gera. É a única medida capaz de zerar a exposição, e por isso encabeça a sequência. Exemplos: substituir um processo que exige solvente clorado por outro que não exige, ou eliminar uma etapa de lavagem manual.\"},{\"t\":\"Substituição\",\"f\":\"2\",\"d\":\"Trocar o produto, o equipamento ou o método por alternativa comprovadamente menos agressiva. Trocar um desengraxante de alta volatilidade por um de base aquosa reduz o risco na origem, sem depender de quem executa a tarefa.\"},{\"t\":\"Controles de engenharia\",\"f\":\"3\",\"d\":\"Atuam sobre a fonte ou sobre o caminho do agente. Exaustão localizada em cabine de pintura, enclausuramento de equipamento ruidoso, bandeja de contenção, isolamento de área e proteção fixa de partes móveis. Valem para todos que circulam ali.\"},{\"t\":\"Controles administrativos\",\"f\":\"4\",\"d\":\"Organizam a forma de trabalhar: procedimento operacional, permissão de trabalho, sinalização, revezamento para reduzir o tempo de exposição, e a própria capacitação. Não eliminam o agente, mas reduzem quem se expõe e por quanto tempo.\"},{\"t\":\"Proteção individual\",\"f\":\"5\",\"d\":\"O EPI é dimensionado sobre o risco residual, aquele que permaneceu depois de todas as medidas anteriores terem sido aplicadas. Ele é a última barreira antes do corpo, e a única que depende do uso correto a cada jornada.\"}],\"guiado\":true},\"x\":4,\"y\":24.5,\"w\":63,\"h\":55.5,\"oculto\":true},{\"z\":1,\"s\":{\"fs\":100,\"anim\":\"subir\"},\"id\":\"e5\",\"t\":\"bloco\",\"bloco\":\"alerta\",\"dados\":{\"tipo\":\"atencao\",\"titulo\":\"O EPI soma, não substitui\",\"texto\":\"A adoção do EPI é cumulativa, nunca substitutiva. Ele se soma às medidas anteriores e não autoriza desligar uma exaustão, remover uma proteção fixa ou dispensar um procedimento, ainda que a implantação seja mais rápida ou menos onerosa.\"},\"x\":4,\"y\":81.5,\"w\":63,\"h\":12,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:58%;height:2.2%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Gerenciamento de riscos</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:10.4%;width:58%;height:5.9%;z-index:1;--trc-fs:1.46;\"><h2>A sequência das medidas de controle</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:17.6%;width:58%;height:5.5%;z-index:1;\"><p>A norma não deixa a escolha livre. As medidas são avaliadas em ordem, e só se passa para a seguinte quando a anterior for tecnicamente inviável ou insuficiente.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:24.5%;width:63%;height:55.5%;z-index:1;--trc-fs:0.95;\"><div class=\"trb trb-passos trb-guiado\" data-bloco=\"passos\" data-guiado=\"1\" data-apos=\"1\"><ol class=\"trb-passos-lista\"><li class=\"trb-passo\" data-gi=\"0\" data-gf=\"1\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">1</span><span class=\"trb-passo-corpo\"><b>Eliminação do risco</b><small>Suprimir o agente ou a etapa que o gera. É a única medida capaz de zerar a exposição, e por isso encabeça a sequência. Exemplos: substituir um processo que exige solvente clorado por outro que não exige, ou eliminar uma etapa de lavagem manual.</small></span></li><li class=\"trb-passo\" data-gi=\"1\" data-gf=\"2\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">2</span><span class=\"trb-passo-corpo\"><b>Substituição</b><small>Trocar o produto, o equipamento ou o método por alternativa comprovadamente menos agressiva. Trocar um desengraxante de alta volatilidade por um de base aquosa reduz o risco na origem, sem depender de quem executa a tarefa.</small></span></li><li class=\"trb-passo\" data-gi=\"2\" data-gf=\"3\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">3</span><span class=\"trb-passo-corpo\"><b>Controles de engenharia</b><small>Atuam sobre a fonte ou sobre o caminho do agente. Exaustão localizada em cabine de pintura, enclausuramento de equipamento ruidoso, bandeja de contenção, isolamento de área e proteção fixa de partes móveis. Valem para todos que circulam ali.</small></span></li><li class=\"trb-passo\" data-gi=\"3\" data-gf=\"4\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">4</span><span class=\"trb-passo-corpo\"><b>Controles administrativos</b><small>Organizam a forma de trabalhar: procedimento operacional, permissão de trabalho, sinalização, revezamento para reduzir o tempo de exposição, e a própria capacitação. Não eliminam o agente, mas reduzem quem se expõe e por quanto tempo.</small></span></li><li class=\"trb-passo\" data-gi=\"4\" data-gf=\"5\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">5</span><span class=\"trb-passo-corpo\"><b>Proteção individual</b><small>O EPI é dimensionado sobre o risco residual, aquele que permaneceu depois de todas as medidas anteriores terem sido aplicadas. Ele é a última barreira antes do corpo, e a única que depende do uso correto a cada jornada.</small></span></li></ol></div></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e5\" style=\"left:4%;top:81.5%;width:63%;height:12%;z-index:1;\"><div class=\"trb trb-alerta trb-alerta-atencao\" data-bloco=\"alerta\"><i class=\"bi bi-exclamation-triangle\"></i><div><b>O EPI soma, não substitui</b><p>A adoção do EPI é cumulativa, nunca substitutiva. Ele se soma às medidas anteriores e não autoriza desligar uma exaustão, remover uma proteção fixa ou dispensar um procedimento, ainda que a implantação seja mais rápida ou menos onerosa.</p></div></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-04 14:44:24', 'herdar'),
(380, 29, 3, 'Por que este treinamento existe', 'esquerda', 'esquerda', 'tema', '#FFFFFF', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'mid', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":58,\"h\":3.8,\"html\":\"<div class=\\\"trc-eyebrow\\\">Base legal<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":12.9,\"w\":58,\"h\":9.9,\"html\":\"<h2>Por que este treinamento existe<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":24.9,\"w\":58,\"h\":12.5,\"html\":\"<p>A norma atribui ao empregador o dever de orientar e treinar sobre o uso adequado, a guarda e a conservação do equipamento. Este é o conteúdo mínimo que a capacitação precisa cobrir, e é o roteiro que seguiremos.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":140,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"checklist\",\"dados\":{\"itens\":[{\"t\":\"Para que serve cada equipamento entregue a você\",\"f\":\"3\"},{\"t\":\"Em quais atividades e por quanto tempo deve ser usado\",\"f\":\"4\"},{\"t\":\"Como colocar, ajustar e verificar se está funcionando\",\"f\":\"5\"},{\"t\":\"Como higienizar e com que periodicidade\",\"f\":\"6\"},{\"t\":\"Como guardar entre uma jornada e outra\",\"f\":\"7\"},{\"t\":\"Quando comunicar e como solicitar substituição\",\"f\":\"8\"}],\"guiado\":true,\"guiaAuto\":true,\"titulo\":\"O conteúdo obrigatório da capacitação\"},\"x\":4,\"y\":33.5,\"w\":63.5,\"h\":45,\"oculto\":true},{\"z\":1,\"s\":{\"fs\":110,\"anim\":\"subir\"},\"id\":\"e5\",\"t\":\"bloco\",\"bloco\":\"alerta\",\"dados\":{\"tipo\":\"ok\",\"titulo\":\"A capacitação também é registrada\",\"texto\":\"A capacitação é registrada com data, conteúdo e identificação de quem participou. Esse registro integra a documentação de segurança da empresa e comprova o cumprimento da obrigação legal perante a fiscalização.\"},\"x\":4,\"y\":80,\"w\":63.5,\"h\":13.5,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:58%;height:3.8%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Base legal</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:12.9%;width:58%;height:9.9%;z-index:1;--trc-fs:1.46;\"><h2>Por que este treinamento existe</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:24.9%;width:58%;height:12.5%;z-index:1;\"><p>A norma atribui ao empregador o dever de orientar e treinar sobre o uso adequado, a guarda e a conservação do equipamento. Este é o conteúdo mínimo que a capacitação precisa cobrir, e é o roteiro que seguiremos.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:33.5%;width:63.5%;height:45%;z-index:1;--trc-fs:1.4;\"><div class=\"trb trb-checklist trb-guiado\" data-bloco=\"checklist\" data-guiado=\"1\" data-apos=\"3\" data-gauto=\"1\"><div class=\"trb-titulo\">O conteúdo obrigatório da capacitação</div><div class=\"trb-checks\"><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"0\" data-gf=\"3\"><i class=\"bi bi-square\"></i><span>Para que serve cada equipamento entregue a você</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"1\" data-gf=\"4\"><i class=\"bi bi-square\"></i><span>Em quais atividades e por quanto tempo deve ser usado</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"2\" data-gf=\"5\"><i class=\"bi bi-square\"></i><span>Como colocar, ajustar e verificar se está funcionando</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"3\" data-gf=\"6\"><i class=\"bi bi-square\"></i><span>Como higienizar e com que periodicidade</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"4\" data-gf=\"7\"><i class=\"bi bi-square\"></i><span>Como guardar entre uma jornada e outra</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"5\" data-gf=\"8\"><i class=\"bi bi-square\"></i><span>Quando comunicar e como solicitar substituição</span></button></div></div></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e5\" style=\"left:4%;top:80%;width:63.5%;height:13.5%;z-index:1;--trc-fs:1.1;\"><div class=\"trb trb-alerta trb-alerta-ok\" data-bloco=\"alerta\"><i class=\"bi bi-check-circle\"></i><div><b>A capacitação também é registrada</b><p>A capacitação é registrada com data, conteúdo e identificação de quem participou. Esse registro integra a documentação de segurança da empresa e comprova o cumprimento da obrigação legal perante a fiscalização.</p></div></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-04 14:46:55', 'herdar'),
(381, 29, 7, 'Verificação 1', 'zoom', 'cheio', 'solido', '#F2F5F9', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'busto', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":92,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Verificação de aprendizagem 1<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":13.2,\"w\":92,\"h\":10.5,\"html\":\"<h2>Analise a situação<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100,\"anim\":\"subir\"},\"id\":\"e3\",\"t\":\"bloco\",\"bloco\":\"quiz\",\"dados\":{\"pergunta\":\"Uma exaustão localizada será instalada em uma área onde hoje se trabalha com respirador. Durante a obra, qual é a conduta correta?\",\"opcoes\":[{\"t\":\"Manter o respirador durante todo o período da obra, com a mesma exigência de uso de sempre\",\"ok\":true},{\"t\":\"Dispensar o respirador, já que a medida coletiva está sendo providenciada\",\"ok\":false},{\"t\":\"Usar o respirador apenas nos horários em que a obra estiver parada\",\"ok\":false},{\"t\":\"Reduzir o tempo de uso pela metade, proporcionalmente ao avanço da obra\",\"ok\":false}],\"feedback\":\"Enquanto a medida coletiva está sendo implantada, o EPI assegura a proteção integral do período. Não há proteção parcial nem proporcional: a exposição continua a mesma até a exaustão entrar em operação.\",\"varias\":false},\"x\":4,\"y\":23.7,\"w\":92,\"h\":66,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:92%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Verificação de aprendizagem 1</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:13.2%;width:92%;height:10.5%;z-index:1;--trc-fs:1.46;\"><h2>Analise a situação</h2></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e3\" style=\"left:4%;top:23.7%;width:92%;height:66%;z-index:1;\"><div class=\"trb trb-quiz\" data-bloco=\"quiz\"><div class=\"trb-quiz-topo\"><i class=\"bi bi-patch-question\"></i><span>Pergunta</span></div><p class=\"trb-quiz-pergunta\">Uma exaustão localizada será instalada em uma área onde hoje se trabalha com respirador. Durante a obra, qual é a conduta correta?</p><div class=\"trb-quiz-ops\"><button type=\"button\" class=\"trb-quiz-op\" data-i=\"0\" data-ok=\"1\"><span class=\"trb-quiz-letra\">A</span><span class=\"trb-quiz-txt\">Manter o respirador durante todo o período da obra, com a mesma exigência de uso de sempre</span><i class=\"bi trb-quiz-icone\"></i></button><button type=\"button\" class=\"trb-quiz-op\" data-i=\"1\" data-ok=\"0\"><span class=\"trb-quiz-letra\">B</span><span class=\"trb-quiz-txt\">Dispensar o respirador, já que a medida coletiva está sendo providenciada</span><i class=\"bi trb-quiz-icone\"></i></button><button type=\"button\" class=\"trb-quiz-op\" data-i=\"2\" data-ok=\"0\"><span class=\"trb-quiz-letra\">C</span><span class=\"trb-quiz-txt\">Usar o respirador apenas nos horários em que a obra estiver parada</span><i class=\"bi trb-quiz-icone\"></i></button><button type=\"button\" class=\"trb-quiz-op\" data-i=\"3\" data-ok=\"0\"><span class=\"trb-quiz-letra\">D</span><span class=\"trb-quiz-txt\">Reduzir o tempo de uso pela metade, proporcionalmente ao avanço da obra</span><i class=\"bi trb-quiz-icone\"></i></button></div><div class=\"trb-quiz-feedback\"><i class=\"bi bi-info-circle\"></i><span>Enquanto a medida coletiva está sendo implantada, o EPI assegura a proteção integral do período. Não há proteção parcial nem proporcional: a exposição continua a mesma até a exaustão entrar em operação.</span></div></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-08-31 09:56:33', 'quiz'),
(382, 29, 8, 'Módulo 02', 'cima', 'esquerda', 'gradiente', '#08243F', '#134E86', 160, NULL, 0, '#FFFFFF', 1, 'direita', 'auto', 'herdar', 1.00, 'upper', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":144,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":33,\"w\":58,\"h\":6,\"html\":\"<div class=\\\"trc-eyebrow\\\" style=\\\"color:#7FC4FF\\\">Módulo 02<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":180,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":41.5,\"w\":58,\"h\":18,\"html\":\"<h2>Certificação, fornecimento e registro<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":104,\"anim\":\"subir\"},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":59.5,\"w\":58,\"h\":10.3,\"html\":\"<p>O Certificado de Aprovação, a gratuidade integral, a ficha de entrega e as obrigações do empregador, do fabricante e do órgão competente.<\\/p>\",\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:33%;width:58%;height:6%;z-index:1;--trc-fs:1.44;\"><div class=\"trc-eyebrow\" style=\"color:#7FC4FF\">Módulo 02</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:41.5%;width:58%;height:18%;z-index:1;--trc-fs:1.8;\"><h2>Certificação, fornecimento e registro</h2></div>\n<div class=\"trc-el trc-texto nv-oculto trv-anim-subir\" id=\"e3\" style=\"left:4%;top:59.5%;width:58%;height:10.3%;z-index:1;--trc-fs:1.04;\"><p>O Certificado de Aprovação, a gratuidade integral, a ficha de entrega e as obrigações do empregador, do fabricante e do órgão competente.</p></div>\n</div>', '', '2026-08-31 07:33:43', '2026-08-31 10:01:27', 'nenhuma'),
(383, 29, 9, 'O Certificado de Aprovação', 'esquerda', 'cheio', 'solido', '#F2F5F9', '#F3F6FA', 160, NULL, 0, NULL, 0, 'direita', 'auto', 'herdar', 1.00, 'herdar', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":92,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Certificação<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":13.2,\"w\":92,\"h\":10.5,\"html\":\"<h2>O Certificado de Aprovação<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":25.9,\"w\":92,\"h\":6.6,\"html\":\"<p>É o documento que separa um equipamento de proteção de um produto qualquer com aparência semelhante. Sem ele, não há como afirmar que o item protege.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":140,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"abas\",\"dados\":{\"itens\":[{\"t\":\"O que é\",\"f\":\"1\",\"d\":\"O Certificado de Aprovação, conhecido pela sigla CA, é o documento emitido pelo órgão nacional competente em segurança e saúde no trabalho. Ele atesta que aquele modelo específico foi submetido a ensaio em laboratório credenciado e aprovado para um risco determinado. Nenhum equipamento pode ser comercializado ou utilizado como EPI sem ele.\"},{\"t\":\"O que consta\",\"f\":\"2\",\"d\":\"Número do certificado, nome e CNPJ do fabricante ou do importador, referência comercial do modelo, descrição do equipamento, prazo de validade do certificado e o risco para o qual foi aprovado. É esse último campo que determina em quais atividades o equipamento pode ser empregado.\"},{\"t\":\"Onde localizar\",\"f\":\"3\",\"d\":\"O número é gravado no próprio equipamento, de forma legível e indelével, o que significa que não deve apagar com o uso normal. Quando a gravação na peça é tecnicamente inviável, ela vai na embalagem original, acompanhada do lote de fabricação. A marcação é o que liga aquela peça específica ao ensaio realizado.\"},{\"t\":\"Como consultar\",\"f\":\"4\",\"d\":\"A situação de cada certificado fica disponível em base pública mantida pelo órgão competente. Informando o número, a consulta retorna o fabricante, o risco aprovado e a validade. O certificado pode estar vencido ou suspenso mesmo com o equipamento novo na prateleira, e nesse caso o item sai de uso.\"}],\"guiado\":true},\"x\":4,\"y\":32.5,\"w\":92,\"h\":40.5,\"oculto\":true},{\"z\":1,\"s\":{\"fs\":125,\"anim\":\"subir\"},\"id\":\"e5\",\"t\":\"bloco\",\"bloco\":\"alerta\",\"dados\":{\"tipo\":\"atencao\",\"titulo\":\"Um certificado, um risco\",\"texto\":\"A aprovação vale para um risco específico. Luva certificada para risco mecânico não substitui luva certificada para agente químico, ainda que o certificado esteja dentro da validade. O risco da aprovação precisa coincidir com o risco da tarefa.\"},\"x\":4,\"y\":76,\"w\":92,\"h\":13.9,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:92%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Certificação</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:13.2%;width:92%;height:10.5%;z-index:1;--trc-fs:1.46;\"><h2>O Certificado de Aprovação</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:25.9%;width:92%;height:6.6%;z-index:1;\"><p>É o documento que separa um equipamento de proteção de um produto qualquer com aparência semelhante. Sem ele, não há como afirmar que o item protege.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:32.5%;width:92%;height:40.5%;z-index:1;--trc-fs:1.4;\"><div class=\"trb trb-abas trb-guiado\" data-bloco=\"abas\" data-guiado=\"1\" data-apos=\"1\"><div class=\"trb-abas-barra\"><button type=\"button\" class=\"trb-aba\" data-i=\"0\" data-gi=\"0\" data-gf=\"1\">O que é</button><button type=\"button\" class=\"trb-aba\" data-i=\"1\" data-gi=\"1\" data-gf=\"2\">O que consta</button><button type=\"button\" class=\"trb-aba\" data-i=\"2\" data-gi=\"2\" data-gf=\"3\">Onde localizar</button><button type=\"button\" class=\"trb-aba\" data-i=\"3\" data-gi=\"3\" data-gf=\"4\">Como consultar</button></div><div class=\"trb-abas-corpo\"><div class=\"trb-aba-painel\" data-i=\"0\">O Certificado de Aprovação, conhecido pela sigla CA, é o documento emitido pelo órgão nacional competente em segurança e saúde no trabalho. Ele atesta que aquele modelo específico foi submetido a ensaio em laboratório credenciado e aprovado para um risco determinado. Nenhum equipamento pode ser comercializado ou utilizado como EPI sem ele.</div><div class=\"trb-aba-painel\" data-i=\"1\">Número do certificado, nome e CNPJ do fabricante ou do importador, referência comercial do modelo, descrição do equipamento, prazo de validade do certificado e o risco para o qual foi aprovado. É esse último campo que determina em quais atividades o equipamento pode ser empregado.</div><div class=\"trb-aba-painel\" data-i=\"2\">O número é gravado no próprio equipamento, de forma legível e indelével, o que significa que não deve apagar com o uso normal. Quando a gravação na peça é tecnicamente inviável, ela vai na embalagem original, acompanhada do lote de fabricação. A marcação é o que liga aquela peça específica ao ensaio realizado.</div><div class=\"trb-aba-painel\" data-i=\"3\">A situação de cada certificado fica disponível em base pública mantida pelo órgão competente. Informando o número, a consulta retorna o fabricante, o risco aprovado e a validade. O certificado pode estar vencido ou suspenso mesmo com o equipamento novo na prateleira, e nesse caso o item sai de uso.</div><div class=\"trb-aba-vazio\">Abra as abas na ordem pedida pelo instrutor.</div></div></div></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e5\" style=\"left:4%;top:76%;width:92%;height:13.9%;z-index:1;--trc-fs:1.25;\"><div class=\"trb trb-alerta trb-alerta-atencao\" data-bloco=\"alerta\"><i class=\"bi bi-exclamation-triangle\"></i><div><b>Um certificado, um risco</b><p>A aprovação vale para um risco específico. Luva certificada para risco mecânico não substitui luva certificada para agente químico, ainda que o certificado esteja dentro da validade. O risco da aprovação precisa coincidir com o risco da tarefa.</p></div></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-04 15:03:33', 'herdar'),
(384, 29, 10, 'Gratuidade integral', 'esquerda', 'esquerda', 'tema', '#FFFFFF', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'mid', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":58,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Fornecimento<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":13.2,\"w\":58,\"h\":10.5,\"html\":\"<h2>Gratuidade integral<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":25.9,\"w\":58,\"h\":9.9,\"html\":\"<p>A norma é objetiva quanto ao custo: o fornecimento do EPI é gratuito. A gratuidade não se limita à primeira entrega e não comporta exceção por motivo da substituição.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":120,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"checklist\",\"dados\":{\"itens\":[{\"t\":\"A primeira entrega, no momento da admissão ou da mudança de atividade\",\"f\":\"2\"},{\"t\":\"Toda substituição, por desgaste natural, dano ou vencimento\",\"f\":\"3\"},{\"t\":\"A troca de modelo ou de tamanho quando o item não se ajusta ao seu corpo\",\"f\":\"4\"},{\"t\":\"A higienização e a manutenção periódica previstas pelo fabricante\",\"f\":\"5\"},{\"t\":\"A reposição do item cujo Certificado de Aprovação foi vencido ou suspenso\",\"f\":\"6\"}],\"guiado\":true,\"guiaAuto\":true,\"titulo\":\"O que a empresa custeia\"},\"x\":4,\"y\":34.5,\"w\":63,\"h\":36.5,\"oculto\":true},{\"z\":1,\"s\":{\"fs\":120,\"anim\":\"subir\"},\"id\":\"e5\",\"t\":\"bloco\",\"bloco\":\"alerta\",\"dados\":{\"tipo\":\"perigo\",\"titulo\":\"Substituição e responsabilidade\",\"texto\":\"Desgaste natural, vencimento, tamanho inadequado e dano ocorrido durante um acidente são substituídos pela empresa, sem custo. Perda ou dano por conduta comprovadamente irregular é apurado caso a caso, conforme as normas internas e a legislação aplicável.\"},\"x\":4,\"y\":73,\"w\":63,\"h\":19,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:58%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Fornecimento</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:13.2%;width:58%;height:10.5%;z-index:1;--trc-fs:1.46;\"><h2>Gratuidade integral</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:25.9%;width:58%;height:9.9%;z-index:1;\"><p>A norma é objetiva quanto ao custo: o fornecimento do EPI é gratuito. A gratuidade não se limita à primeira entrega e não comporta exceção por motivo da substituição.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:34.5%;width:63%;height:36.5%;z-index:1;--trc-fs:1.2;\"><div class=\"trb trb-checklist trb-guiado\" data-bloco=\"checklist\" data-guiado=\"1\" data-apos=\"2\" data-gauto=\"1\"><div class=\"trb-titulo\">O que a empresa custeia</div><div class=\"trb-checks\"><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"0\" data-gf=\"2\"><i class=\"bi bi-square\"></i><span>A primeira entrega, no momento da admissão ou da mudança de atividade</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"1\" data-gf=\"3\"><i class=\"bi bi-square\"></i><span>Toda substituição, por desgaste natural, dano ou vencimento</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"2\" data-gf=\"4\"><i class=\"bi bi-square\"></i><span>A troca de modelo ou de tamanho quando o item não se ajusta ao seu corpo</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"3\" data-gf=\"5\"><i class=\"bi bi-square\"></i><span>A higienização e a manutenção periódica previstas pelo fabricante</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"4\" data-gf=\"6\"><i class=\"bi bi-square\"></i><span>A reposição do item cujo Certificado de Aprovação foi vencido ou suspenso</span></button></div></div></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e5\" style=\"left:4%;top:73%;width:63%;height:19%;z-index:1;--trc-fs:1.2;\"><div class=\"trb trb-alerta trb-alerta-perigo\" data-bloco=\"alerta\"><i class=\"bi bi-shield-exclamation\"></i><div><b>Substituição e responsabilidade</b><p>Desgaste natural, vencimento, tamanho inadequado e dano ocorrido durante um acidente são substituídos pela empresa, sem custo. Perda ou dano por conduta comprovadamente irregular é apurado caso a caso, conforme as normas internas e a legislação aplicável.</p></div></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-04 15:12:04', 'herdar');
INSERT INTO `treinamentos_slides` (`id`, `apresentacao_id`, `ordem`, `titulo`, `transicao`, `layout`, `fundo_tipo`, `fundo_cor`, `fundo_cor2`, `fundo_angulo`, `fundo_imagem`, `fundo_escurecer`, `cor_texto`, `instrutor_visivel`, `instrutor_posicao`, `instrutor_lado_conteudo`, `instrutor_giro`, `instrutor_escala`, `instrutor_camera`, `conteudo_html`, `resumo`, `criado_em`, `atualizado_em`, `exigencia`) VALUES
(385, 29, 11, 'A ficha de EPI e a sua assinatura', 'esquerda', 'esquerda', 'tema', '#FFFFFF', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'mid', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":58,\"h\":3.1,\"html\":\"<div class=\\\"trc-eyebrow\\\">Registro de entrega<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":11.8,\"w\":58,\"h\":8.1,\"html\":\"<h2>A ficha de EPI e a sua assinatura<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":21.6,\"w\":58,\"h\":7.6,\"html\":\"<p>Toda entrega é registrada. O registro comprova o fornecimento, documenta a orientação prestada e assegura a rastreabilidade de cada item.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":110,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"passos\",\"dados\":{\"itens\":[{\"t\":\"Definição na ficha da atividade\",\"f\":\"1\",\"d\":\"O levantamento de riscos determina os equipamentos exigidos para cada atividade, com a certificação correspondente e a periodicidade de troca. A ficha de EPI nasce desse levantamento e é o documento que orienta a entrega.\"},{\"t\":\"Conferência antes de receber\",\"f\":\"2\",\"d\":\"Confira modelo, número do CA legível, validade do certificado, tamanho e estado de conservação do item. Divergência em qualquer um desses pontos se resolve no momento da entrega, porque depois da assinatura o registro passa a dizer que estava tudo conforme.\"},{\"t\":\"Assinatura do recebimento\",\"f\":\"3\",\"d\":\"A assinatura, física ou eletrônica, confirma duas coisas distintas: que você recebeu o equipamento descrito e que recebeu orientação sobre o uso correto. É por isso que a conferência precisa vir antes dela, e não depois.\"},{\"t\":\"Histórico e rastreabilidade\",\"f\":\"6\",\"d\":\"O registro permanece disponível para consulta a qualquer momento, por você, pela empresa e pela fiscalização. Ele demonstra o cumprimento da obrigação de fornecer, sustenta a análise de qualquer ocorrência e organiza a previsão das próximas trocas.\"}],\"guiado\":true},\"x\":4,\"y\":31,\"w\":63.5,\"h\":62.1,\"oculto\":false}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:58%;height:3.1%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Registro de entrega</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:11.8%;width:58%;height:8.1%;z-index:1;--trc-fs:1.46;\"><h2>A ficha de EPI e a sua assinatura</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:21.6%;width:58%;height:7.6%;z-index:1;\"><p>Toda entrega é registrada. O registro comprova o fornecimento, documenta a orientação prestada e assegura a rastreabilidade de cada item.</p></div>\n<div class=\"trc-el trc-bloco trv-anim-subir\" id=\"e4\" style=\"left:4%;top:31%;width:63.5%;height:62.1%;z-index:1;--trc-fs:1.1;\"><div class=\"trb trb-passos trb-guiado\" data-bloco=\"passos\" data-guiado=\"1\" data-apos=\"1\"><ol class=\"trb-passos-lista\"><li class=\"trb-passo\" data-gi=\"0\" data-gf=\"1\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">1</span><span class=\"trb-passo-corpo\"><b>Definição na ficha da atividade</b><small>O levantamento de riscos determina os equipamentos exigidos para cada atividade, com a certificação correspondente e a periodicidade de troca. A ficha de EPI nasce desse levantamento e é o documento que orienta a entrega.</small></span></li><li class=\"trb-passo\" data-gi=\"1\" data-gf=\"2\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">2</span><span class=\"trb-passo-corpo\"><b>Conferência antes de receber</b><small>Confira modelo, número do CA legível, validade do certificado, tamanho e estado de conservação do item. Divergência em qualquer um desses pontos se resolve no momento da entrega, porque depois da assinatura o registro passa a dizer que estava tudo conforme.</small></span></li><li class=\"trb-passo\" data-gi=\"2\" data-gf=\"3\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">3</span><span class=\"trb-passo-corpo\"><b>Assinatura do recebimento</b><small>A assinatura, física ou eletrônica, confirma duas coisas distintas: que você recebeu o equipamento descrito e que recebeu orientação sobre o uso correto. É por isso que a conferência precisa vir antes dela, e não depois.</small></span></li><li class=\"trb-passo\" data-gi=\"3\" data-gf=\"6\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">4</span><span class=\"trb-passo-corpo\"><b>Histórico e rastreabilidade</b><small>O registro permanece disponível para consulta a qualquer momento, por você, pela empresa e pela fiscalização. Ele demonstra o cumprimento da obrigação de fornecer, sustenta a análise de qualquer ocorrência e organiza a previsão das próximas trocas.</small></span></li></ol></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-04 15:14:29', 'herdar'),
(386, 29, 12, 'O que compete ao empregador', 'esquerda', 'esquerda', 'tema', '#FFFFFF', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'busto', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":58,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Responsabilidades<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":13.2,\"w\":58,\"h\":10.5,\"html\":\"<h2>O que compete ao empregador<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":25.9,\"w\":58,\"h\":9.9,\"html\":\"<p>São oito obrigações. Você não precisa memorizá-las, mas precisa reconhecê-las, porque é assim que se percebe quando alguma deixou de ser cumprida.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":140,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"checklist\",\"dados\":{\"itens\":[{\"t\":\"Adquirir o equipamento adequado ao risco da atividade\",\"f\":2},{\"t\":\"Fornecer somente equipamento com Certificado de Aprovação válido\",\"f\":\"3\"},{\"t\":\"Orientar e treinar sobre uso, guarda e conservação\",\"f\":\"4\"},{\"t\":\"Exigir o uso durante todo o período de exposição\",\"f\":\"5\"},{\"t\":\"Substituir de imediato o item danificado, extraviado ou vencido\",\"f\":\"6\"},{\"t\":\"Responsabilizar-se pela higienização e pela manutenção periódica\",\"f\":\"7\"},{\"t\":\"Registrar o fornecimento e manter o histórico disponível\",\"f\":\"8\"},{\"t\":\"Comunicar ao órgão competente irregularidade constatada no equipamento\",\"f\":\"9\"}],\"guiado\":true,\"guiaAuto\":true,\"titulo\":\"Obrigações do empregador\"},\"x\":4,\"y\":33.5,\"w\":63,\"h\":59.5,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:58%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Responsabilidades</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:13.2%;width:58%;height:10.5%;z-index:1;--trc-fs:1.46;\"><h2>O que compete ao empregador</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:25.9%;width:58%;height:9.9%;z-index:1;\"><p>São oito obrigações. Você não precisa memorizá-las, mas precisa reconhecê-las, porque é assim que se percebe quando alguma deixou de ser cumprida.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:33.5%;width:63%;height:59.5%;z-index:1;--trc-fs:1.4;\"><div class=\"trb trb-checklist trb-guiado\" data-bloco=\"checklist\" data-guiado=\"1\" data-apos=\"2\" data-gauto=\"1\"><div class=\"trb-titulo\">Obrigações do empregador</div><div class=\"trb-checks\"><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"0\" data-gf=\"2\"><i class=\"bi bi-square\"></i><span>Adquirir o equipamento adequado ao risco da atividade</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"1\" data-gf=\"3\"><i class=\"bi bi-square\"></i><span>Fornecer somente equipamento com Certificado de Aprovação válido</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"2\" data-gf=\"4\"><i class=\"bi bi-square\"></i><span>Orientar e treinar sobre uso, guarda e conservação</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"3\" data-gf=\"5\"><i class=\"bi bi-square\"></i><span>Exigir o uso durante todo o período de exposição</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"4\" data-gf=\"6\"><i class=\"bi bi-square\"></i><span>Substituir de imediato o item danificado, extraviado ou vencido</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"5\" data-gf=\"7\"><i class=\"bi bi-square\"></i><span>Responsabilizar-se pela higienização e pela manutenção periódica</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"6\" data-gf=\"8\"><i class=\"bi bi-square\"></i><span>Registrar o fornecimento e manter o histórico disponível</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"7\" data-gf=\"9\"><i class=\"bi bi-square\"></i><span>Comunicar ao órgão competente irregularidade constatada no equipamento</span></button></div></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-04 15:20:47', 'herdar'),
(387, 29, 13, 'Quem fabrica e quem fiscaliza', 'esquerda', 'esquerda', 'tema', '#FFFFFF', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'mid', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":58,\"h\":3.5,\"html\":\"<div class=\\\"trc-eyebrow\\\">Responsabilidades<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":12.4,\"w\":58,\"h\":9.3,\"html\":\"<h2>Quem fabrica e quem fiscaliza<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":23.7,\"w\":58,\"h\":8.8,\"html\":\"<p>A norma também distribui obrigações fora da relação de emprego. Conhecer essa parte ajuda a entender por que o número do CA tem o peso que tem.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":115,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"revelar\",\"dados\":{\"itens\":[{\"t\":\"Fabricante e importador\",\"f\":\"1\",\"d\":\"Precisam estar cadastrados no órgão competente, solicitar o Certificado de Aprovação para cada modelo, renová-lo dentro do prazo e requerer certificado novo sempre que alterarem material, desenho ou processo. Respondem pela qualidade de toda a produção, e não apenas da amostra ensaiada, e só podem comercializar com certificado válido.\"},{\"t\":\"Órgão nacional competente\",\"f\":\"2\",\"d\":\"Emite, renova, fiscaliza, suspende e cancela o Certificado de Aprovação. Mantém a base pública de consulta e credencia os laboratórios de ensaio. Suspenso o certificado, o equipamento sai de uso, mesmo que esteja novo e lacrado no almoxarifado.\"},{\"t\":\"Por que isso chega até você\",\"f\":\"3\",\"d\":\"Essa cadeia é o que dá sentido ao número gravado no equipamento. Quando você confere o CA antes de usar, está verificando o resultado de todo esse encadeamento: alguém ensaiou, alguém aprovou e alguém continua fiscalizando aquele modelo.\"}],\"guiado\":true,\"guiaAuto\":true},\"x\":4,\"y\":41.5,\"w\":63.5,\"h\":51.5,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:58%;height:3.5%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Responsabilidades</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:12.4%;width:58%;height:9.3%;z-index:1;--trc-fs:1.46;\"><h2>Quem fabrica e quem fiscaliza</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:23.7%;width:58%;height:8.8%;z-index:1;\"><p>A norma também distribui obrigações fora da relação de emprego. Conhecer essa parte ajuda a entender por que o número do CA tem o peso que tem.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:41.5%;width:63.5%;height:51.5%;z-index:1;--trc-fs:1.15;\"><div class=\"trb trb-revelar trb-guiado\" data-bloco=\"revelar\" data-guiado=\"1\" data-apos=\"1\" data-gauto=\"1\"><div class=\"trb-cards\"><button type=\"button\" class=\"trb-card\" data-bloco-ac=\"revelar\" data-gi=\"0\" data-gf=\"1\"><span class=\"trb-card-frente\"><span>Fabricante e importador</span><i class=\"bi bi-plus-circle\"></i></span><span class=\"trb-card-verso\">Precisam estar cadastrados no órgão competente, solicitar o Certificado de Aprovação para cada modelo, renová-lo dentro do prazo e requerer certificado novo sempre que alterarem material, desenho ou processo. Respondem pela qualidade de toda a produção, e não apenas da amostra ensaiada, e só podem comercializar com certificado válido.</span></button><button type=\"button\" class=\"trb-card\" data-bloco-ac=\"revelar\" data-gi=\"1\" data-gf=\"2\"><span class=\"trb-card-frente\"><span>Órgão nacional competente</span><i class=\"bi bi-plus-circle\"></i></span><span class=\"trb-card-verso\">Emite, renova, fiscaliza, suspende e cancela o Certificado de Aprovação. Mantém a base pública de consulta e credencia os laboratórios de ensaio. Suspenso o certificado, o equipamento sai de uso, mesmo que esteja novo e lacrado no almoxarifado.</span></button><button type=\"button\" class=\"trb-card\" data-bloco-ac=\"revelar\" data-gi=\"2\" data-gf=\"3\"><span class=\"trb-card-frente\"><span>Por que isso chega até você</span><i class=\"bi bi-plus-circle\"></i></span><span class=\"trb-card-verso\">Essa cadeia é o que dá sentido ao número gravado no equipamento. Quando você confere o CA antes de usar, está verificando o resultado de todo esse encadeamento: alguém ensaiou, alguém aprovou e alguém continua fiscalizando aquele modelo.</span></button></div></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-08-31 11:06:33', 'herdar'),
(388, 29, 14, 'Verificação 2', 'zoom', 'cheio', 'solido', '#F2F5F9', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'tresquartos', 1.00, 'head', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":92,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Verificação de aprendizagem 2<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":13.2,\"w\":92,\"h\":10.5,\"html\":\"<h2>Analise a situação<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":120,\"anim\":\"subir\"},\"id\":\"e3\",\"t\":\"bloco\",\"bloco\":\"quiz\",\"dados\":{\"pergunta\":\"Ao receber um par de luvas, você percebe que a gravação do CA na peça está apagada, embora a caixa traga um certificado válido. Como proceder?\",\"opcoes\":[{\"t\":\"Não utilizar e comunicar, porque sem a marcação legível não é possível vincular aquela peça ao ensaio\",\"ok\":true},{\"t\":\"Utilizar normalmente, pois o certificado da embalagem comprova a aprovação\",\"ok\":false},{\"t\":\"Utilizar apenas em atividades de curta duração até a próxima entrega\",\"ok\":false},{\"t\":\"Anotar o número da embalagem na própria luva com caneta permanente\",\"ok\":false}],\"feedback\":\"A gravação no equipamento é o elemento que liga aquela peça específica ao ensaio realizado. Sem ela, a embalagem pode corresponder a outro lote ou a outro modelo. A conduta é não utilizar e solicitar substituição.\",\"varias\":false},\"x\":4,\"y\":26.25,\"w\":92,\"h\":66.5,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:92%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Verificação de aprendizagem 2</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:13.2%;width:92%;height:10.5%;z-index:1;--trc-fs:1.46;\"><h2>Analise a situação</h2></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e3\" style=\"left:4%;top:26.25%;width:92%;height:66.5%;z-index:1;--trc-fs:1.2;\"><div class=\"trb trb-quiz\" data-bloco=\"quiz\"><div class=\"trb-quiz-topo\"><i class=\"bi bi-patch-question\"></i><span>Pergunta</span></div><p class=\"trb-quiz-pergunta\">Ao receber um par de luvas, você percebe que a gravação do CA na peça está apagada, embora a caixa traga um certificado válido. Como proceder?</p><div class=\"trb-quiz-ops\"><button type=\"button\" class=\"trb-quiz-op\" data-i=\"0\" data-ok=\"1\"><span class=\"trb-quiz-letra\">A</span><span class=\"trb-quiz-txt\">Não utilizar e comunicar, porque sem a marcação legível não é possível vincular aquela peça ao ensaio</span><i class=\"bi trb-quiz-icone\"></i></button><button type=\"button\" class=\"trb-quiz-op\" data-i=\"1\" data-ok=\"0\"><span class=\"trb-quiz-letra\">B</span><span class=\"trb-quiz-txt\">Utilizar normalmente, pois o certificado da embalagem comprova a aprovação</span><i class=\"bi trb-quiz-icone\"></i></button><button type=\"button\" class=\"trb-quiz-op\" data-i=\"2\" data-ok=\"0\"><span class=\"trb-quiz-letra\">C</span><span class=\"trb-quiz-txt\">Utilizar apenas em atividades de curta duração até a próxima entrega</span><i class=\"bi trb-quiz-icone\"></i></button><button type=\"button\" class=\"trb-quiz-op\" data-i=\"3\" data-ok=\"0\"><span class=\"trb-quiz-letra\">D</span><span class=\"trb-quiz-txt\">Anotar o número da embalagem na própria luva com caneta permanente</span><i class=\"bi trb-quiz-icone\"></i></button></div><div class=\"trb-quiz-feedback\"><i class=\"bi bi-info-circle\"></i><span>A gravação no equipamento é o elemento que liga aquela peça específica ao ensaio realizado. Sem ela, a embalagem pode corresponder a outro lote ou a outro modelo. A conduta é não utilizar e solicitar substituição.</span></div></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-08-31 11:10:11', 'quiz'),
(389, 29, 15, 'Módulo 03', 'cima', 'esquerda', 'gradiente', '#08243F', '#134E86', 160, NULL, 0, '#FFFFFF', 1, 'direita', 'auto', 'herdar', 1.00, 'upper', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":144,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":33,\"w\":58,\"h\":6,\"html\":\"<div class=\\\"trc-eyebrow\\\" style=\\\"color:#7FC4FF\\\">Módulo 03<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":180,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":41.2,\"w\":58,\"h\":13,\"html\":\"<h2>As famílias de equipamento<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":104,\"anim\":\"subir\"},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":56.4,\"w\":58,\"h\":6.9,\"html\":\"<p>Cada tipo adotado na empresa, com a proteção que oferece, o uso correto, a higienização e a guarda.<\\/p>\",\"oculto\":true}]}</script>\r\n<div class=\"trc-palco\">\r\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:33%;width:58%;height:6%;z-index:1;--trc-fs:1.44;\"><div class=\"trc-eyebrow\" style=\"color:#7FC4FF\">Módulo 03</div></div>\r\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:41.2%;width:58%;height:13%;z-index:1;--trc-fs:1.8;\"><h2>As famílias de equipamento</h2></div>\r\n<div class=\"trc-el trc-texto nv-oculto trv-anim-subir\" id=\"e3\" style=\"left:4%;top:56.4%;width:58%;height:6.9%;z-index:1;--trc-fs:1.04;\"><p>Cada tipo adotado na empresa, com a proteção que oferece, o uso correto, a higienização e a guarda.</p></div>\r\n</div>', NULL, '2026-08-31 07:33:43', '2026-09-09 15:38:57', 'nenhuma'),
(390, 29, 16, 'Creme protetor', 'esquerda', 'cheio', 'solido', '#F2F5F9', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'head', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":92,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Proteção das mãos<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":13.2,\"w\":92,\"h\":10.5,\"html\":\"<h2>Creme protetor<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":25.9,\"w\":70,\"h\":9.9,\"html\":\"<p>É o equipamento de proteção individual mais discreto do conjunto e um dos mais relevantes em atividades com manuseio de óleo, graxa, combustível e produto de limpeza. Assim como qualquer outro EPI, possui Certificado de Aprovação.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":135,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"abas\",\"dados\":{\"itens\":[{\"t\":\"Contra o que protege\",\"f\":\"1\",\"d\":\"O creme protetor forma sobre a pele uma película que reduz o contato direto e a absorção de óleo, graxa, combustível, fluido hidráulico e produto de limpeza. Reduz a incidência de dermatite de contato, ressecamento e rachadura, que estão entre as causas mais frequentes de afastamento em atividades com manuseio de químicos.\"},{\"t\":\"Como aplicar\",\"f\":\"2\",\"d\":\"Aplique com as mãos limpas e secas, antes de iniciar a atividade. Espalhe no dorso, na palma, nos vãos entre os dedos, ao redor das unhas e no punho, que são justamente os pontos esquecidos e por onde o produto penetra. Aguarde a absorção antes de calçar a luva.\"},{\"t\":\"Quando reaplicar\",\"f\":\"3\",\"d\":\"A película é removida por água, por solvente e pela transpiração ao longo da jornada. Reaplique após cada higienização das mãos, sempre que retirar a luva e ao retomar a atividade depois de intervalos prolongados.\"},{\"t\":\"Guarda e limites\",\"f\":\"4\",\"d\":\"Mantenha a embalagem fechada, em local fresco e ao abrigo da luz, e observe a validade impressa. O creme protetor não substitui a luva: ele atua sobre o contato incidental, e não sobre imersão, respingo quente, corte ou perfuração.\"}],\"guiado\":true},\"x\":4,\"y\":35.8,\"w\":92,\"h\":34,\"oculto\":true},{\"z\":1,\"s\":{\"fs\":125,\"anim\":\"subir\"},\"id\":\"e5\",\"t\":\"bloco\",\"bloco\":\"alerta\",\"dados\":{\"tipo\":\"perigo\",\"titulo\":\"Protetor não é hidratante\",\"texto\":\"Creme protetor e creme hidratante são produtos distintos. O protetor tem registro como EPI e número de CA, e é aplicado antes e durante a jornada. O hidratante atua na recuperação da pele após o trabalho e não oferece barreira química.\"},\"x\":4,\"y\":69.8,\"w\":62,\"h\":18,\"oculto\":true},{\"t\":\"imagem\",\"x\":27.5,\"y\":39.5,\"w\":34,\"h\":40,\"src\":\"img-20260831-113408-2d4d2e.png\",\"s\":{\"fit\":\"cover\",\"br\":14,\"sh\":0,\"anim\":\"subir\",\"zoom\":1,\"focoX\":0,\"focoY\":51,\"zoom2\":4,\"focoX2\":100,\"focoY2\":100,\"giro2\":\"0\",\"giro\":\"0\",\"hov\":\"\",\"imgDur\":1,\"voltaSeg\":3},\"id\":\"e6\",\"z\":2,\"oculto\":true},{\"t\":\"imagem\",\"x\":84.5,\"y\":3.8999999999999986,\"w\":15,\"h\":22,\"src\":\"img-20260831-120914-e8e3ad.png\",\"s\":{\"fit\":\"cover\",\"br\":14,\"sh\":0,\"anim\":\"surgir\",\"giro\":\"0\"},\"id\":\"e7\",\"z\":3,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:92%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Proteção das mãos</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:13.2%;width:92%;height:10.5%;z-index:1;--trc-fs:1.46;\"><h2>Creme protetor</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:25.9%;width:70%;height:9.9%;z-index:1;\"><p>É o equipamento de proteção individual mais discreto do conjunto e um dos mais relevantes em atividades com manuseio de óleo, graxa, combustível e produto de limpeza. Assim como qualquer outro EPI, possui Certificado de Aprovação.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:35.8%;width:92%;height:34%;z-index:1;--trc-fs:1.35;\"><div class=\"trb trb-abas trb-guiado\" data-bloco=\"abas\" data-guiado=\"1\" data-apos=\"1\"><div class=\"trb-abas-barra\"><button type=\"button\" class=\"trb-aba\" data-i=\"0\" data-gi=\"0\" data-gf=\"1\">Contra o que protege</button><button type=\"button\" class=\"trb-aba\" data-i=\"1\" data-gi=\"1\" data-gf=\"2\">Como aplicar</button><button type=\"button\" class=\"trb-aba\" data-i=\"2\" data-gi=\"2\" data-gf=\"3\">Quando reaplicar</button><button type=\"button\" class=\"trb-aba\" data-i=\"3\" data-gi=\"3\" data-gf=\"4\">Guarda e limites</button></div><div class=\"trb-abas-corpo\"><div class=\"trb-aba-painel\" data-i=\"0\">O creme protetor forma sobre a pele uma película que reduz o contato direto e a absorção de óleo, graxa, combustível, fluido hidráulico e produto de limpeza. Reduz a incidência de dermatite de contato, ressecamento e rachadura, que estão entre as causas mais frequentes de afastamento em atividades com manuseio de químicos.</div><div class=\"trb-aba-painel\" data-i=\"1\">Aplique com as mãos limpas e secas, antes de iniciar a atividade. Espalhe no dorso, na palma, nos vãos entre os dedos, ao redor das unhas e no punho, que são justamente os pontos esquecidos e por onde o produto penetra. Aguarde a absorção antes de calçar a luva.</div><div class=\"trb-aba-painel\" data-i=\"2\">A película é removida por água, por solvente e pela transpiração ao longo da jornada. Reaplique após cada higienização das mãos, sempre que retirar a luva e ao retomar a atividade depois de intervalos prolongados.</div><div class=\"trb-aba-painel\" data-i=\"3\">Mantenha a embalagem fechada, em local fresco e ao abrigo da luz, e observe a validade impressa. O creme protetor não substitui a luva: ele atua sobre o contato incidental, e não sobre imersão, respingo quente, corte ou perfuração.</div><div class=\"trb-aba-vazio\">Abra as abas na ordem pedida pelo instrutor.</div></div></div></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e5\" style=\"left:4%;top:69.8%;width:62%;height:18%;z-index:1;--trc-fs:1.25;\"><div class=\"trb trb-alerta trb-alerta-perigo\" data-bloco=\"alerta\"><i class=\"bi bi-shield-exclamation\"></i><div><b>Protetor não é hidratante</b><p>Creme protetor e creme hidratante são produtos distintos. O protetor tem registro como EPI e número de CA, e é aplicado antes e durante a jornada. O hidratante atua na recuperação da pele após o trabalho e não oferece barreira química.</p></div></div></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-subir\" id=\"e6\" data-volta=\"3\" style=\"left:27.5%;top:39.5%;width:34%;height:40%;z-index:2;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:0%;--trc-img-y:51%;--trc-img-zoom2:4;--trc-img-giro2:0deg;--trc-img-x2:100%;--trc-img-y2:100%;--trc-img-dur:1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-113408-2d4d2e.png\" alt=\"\" style=\"object-fit:cover\"></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-surgir\" id=\"e7\" style=\"left:84.5%;top:3.8999999999999986%;width:15%;height:22%;z-index:3;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-120914-e8e3ad.png\" alt=\"\" style=\"object-fit:cover\"></div>\n</div>', '', '2026-08-31 07:33:43', '2026-08-31 12:15:38', 'herdar'),
(391, 29, 17, 'Luvas: uma para cada agente', 'esquerda', 'cheio', 'solido', '#F2F5F9', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'busto', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":92,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Proteção das mãos<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":13.2,\"w\":92,\"h\":10.5,\"html\":\"<h2>Luvas: uma para cada agente<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":25.9,\"w\":62.5,\"h\":6.6,\"html\":\"<p>Não existe luva de uso geral. Cada modelo é ensaiado contra um agente determinado, e a seleção parte da tarefa que será executada, não da disponibilidade do almoxarifado.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":135,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"abas\",\"dados\":{\"itens\":[{\"t\":\"Risco mecânico\",\"f\":\"1\",\"d\":\"Protege contra corte, abrasão, perfuração e rasgo em desmontagem, manuseio de peças, chaparia e movimentação de materiais. Não oferece barreira química nem térmica. Inspecione furos e desgaste nas pontas dos dedos antes de calçar, higienize conforme a orientação do fabricante e guarde seca, longe de fonte de calor.\"},{\"t\":\"Risco químico\",\"f\":\"2\",\"d\":\"Indicada para desengraxante, solvente, óleo, combustível e produto de limpeza. O material é escolhido pelo produto manipulado, e cada combinação tem um tempo máximo de resistência. Luva úmida por dentro deixou de proteger. Enxágue externamente antes de retirar, seque pelo avesso quando o fabricante permitir e descarte no prazo indicado.\"},{\"t\":\"Risco térmico\",\"f\":\"3\",\"d\":\"Para manuseio de peças aquecidas, sistemas de escape e atividades a quente. A proteção depende de a luva estar seca: úmida, ela conduz calor e provoca queimadura mais rápida do que a mão desprotegida. Guarde em local ventilado e retire de uso ao primeiro sinal de carbonização ou enrijecimento.\"},{\"t\":\"Risco elétrico\",\"f\":\"4\",\"d\":\"Luva isolante para intervenção em instalações energizadas, com classe de tensão compatível com o circuito. Exige inspeção visual e teste de estanqueidade antes de cada uso, porque um furo mínimo já anula a proteção. Guarda em estojo próprio, sem dobrar, ao abrigo de luz, calor, óleo e ozônio, com ensaio periódico registrado.\"}],\"guiado\":true},\"x\":4,\"y\":32.5,\"w\":92,\"h\":43.5,\"oculto\":true},{\"z\":1,\"s\":{\"fs\":115,\"anim\":\"subir\"},\"id\":\"e5\",\"t\":\"bloco\",\"bloco\":\"alerta\",\"dados\":{\"tipo\":\"perigo\",\"titulo\":\"Partes girantes exigem consulta ao procedimento\",\"texto\":\"Em atividades junto a partes girantes, como furadeira de bancada, esmeril, torno e eixos em rotação, a luva pode ser arrastada e conduzir a mão ao ponto de risco. Nesses casos a orientação vem do procedimento da tarefa, que pode vedar o uso.\"},\"x\":4,\"y\":74.5,\"w\":92,\"h\":13.9,\"oculto\":true},{\"t\":\"imagem\",\"x\":23,\"y\":43.5,\"w\":34,\"h\":40,\"src\":\"img-20260831-133509-2b07b0.png\",\"s\":{\"fit\":\"cover\",\"br\":14,\"sh\":0,\"anim\":\"esquerda\",\"zoom2\":1},\"id\":\"e6\",\"z\":2,\"oculto\":true},{\"t\":\"imagem\",\"x\":23,\"y\":43.5,\"w\":34,\"h\":40,\"src\":\"img-20260831-133942-925770.png\",\"s\":{\"fit\":\"contain\",\"br\":14,\"sh\":0,\"anim\":\"esquerda\"},\"id\":\"e7\",\"z\":3,\"oculto\":true},{\"t\":\"imagem\",\"x\":23,\"y\":43.5,\"w\":34,\"h\":40,\"src\":\"img-20260831-133958-617b8e.png\",\"s\":{\"fit\":\"contain\",\"br\":14,\"sh\":0,\"anim\":\"esquerda\"},\"id\":\"e8\",\"z\":4,\"oculto\":true},{\"t\":\"imagem\",\"x\":23,\"y\":43.5,\"w\":34,\"h\":40,\"src\":\"img-20260831-134014-082953.png\",\"s\":{\"fit\":\"contain\",\"br\":14,\"sh\":0,\"anim\":\"esquerda\",\"zoom\":1.25},\"id\":\"e9\",\"z\":5,\"oculto\":true},{\"t\":\"imagem\",\"x\":85,\"y\":2,\"w\":13,\"h\":26,\"src\":\"img-20260831-134539-9df56b.png\",\"s\":{\"fit\":\"contain\",\"br\":14,\"sh\":0,\"anim\":\"zoom\"},\"id\":\"e10\",\"z\":6,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:92%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Proteção das mãos</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:13.2%;width:92%;height:10.5%;z-index:1;--trc-fs:1.46;\"><h2>Luvas: uma para cada agente</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:25.9%;width:62.5%;height:6.6%;z-index:1;\"><p>Não existe luva de uso geral. Cada modelo é ensaiado contra um agente determinado, e a seleção parte da tarefa que será executada, não da disponibilidade do almoxarifado.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:32.5%;width:92%;height:43.5%;z-index:1;--trc-fs:1.35;\"><div class=\"trb trb-abas trb-guiado\" data-bloco=\"abas\" data-guiado=\"1\" data-apos=\"1\"><div class=\"trb-abas-barra\"><button type=\"button\" class=\"trb-aba\" data-i=\"0\" data-gi=\"0\" data-gf=\"1\">Risco mecânico</button><button type=\"button\" class=\"trb-aba\" data-i=\"1\" data-gi=\"1\" data-gf=\"2\">Risco químico</button><button type=\"button\" class=\"trb-aba\" data-i=\"2\" data-gi=\"2\" data-gf=\"3\">Risco térmico</button><button type=\"button\" class=\"trb-aba\" data-i=\"3\" data-gi=\"3\" data-gf=\"4\">Risco elétrico</button></div><div class=\"trb-abas-corpo\"><div class=\"trb-aba-painel\" data-i=\"0\">Protege contra corte, abrasão, perfuração e rasgo em desmontagem, manuseio de peças, chaparia e movimentação de materiais. Não oferece barreira química nem térmica. Inspecione furos e desgaste nas pontas dos dedos antes de calçar, higienize conforme a orientação do fabricante e guarde seca, longe de fonte de calor.</div><div class=\"trb-aba-painel\" data-i=\"1\">Indicada para desengraxante, solvente, óleo, combustível e produto de limpeza. O material é escolhido pelo produto manipulado, e cada combinação tem um tempo máximo de resistência. Luva úmida por dentro deixou de proteger. Enxágue externamente antes de retirar, seque pelo avesso quando o fabricante permitir e descarte no prazo indicado.</div><div class=\"trb-aba-painel\" data-i=\"2\">Para manuseio de peças aquecidas, sistemas de escape e atividades a quente. A proteção depende de a luva estar seca: úmida, ela conduz calor e provoca queimadura mais rápida do que a mão desprotegida. Guarde em local ventilado e retire de uso ao primeiro sinal de carbonização ou enrijecimento.</div><div class=\"trb-aba-painel\" data-i=\"3\">Luva isolante para intervenção em instalações energizadas, com classe de tensão compatível com o circuito. Exige inspeção visual e teste de estanqueidade antes de cada uso, porque um furo mínimo já anula a proteção. Guarda em estojo próprio, sem dobrar, ao abrigo de luz, calor, óleo e ozônio, com ensaio periódico registrado.</div><div class=\"trb-aba-vazio\">Abra as abas na ordem pedida pelo instrutor.</div></div></div></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e5\" style=\"left:4%;top:74.5%;width:92%;height:13.9%;z-index:1;--trc-fs:1.15;\"><div class=\"trb trb-alerta trb-alerta-perigo\" data-bloco=\"alerta\"><i class=\"bi bi-shield-exclamation\"></i><div><b>Partes girantes exigem consulta ao procedimento</b><p>Em atividades junto a partes girantes, como furadeira de bancada, esmeril, torno e eixos em rotação, a luva pode ser arrastada e conduzir a mão ao ponto de risco. Nesses casos a orientação vem do procedimento da tarefa, que pode vedar o uso.</p></div></div></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-esquerda\" id=\"e6\" style=\"left:23%;top:43.5%;width:34%;height:40%;z-index:2;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-133509-2b07b0.png\" alt=\"\" style=\"object-fit:cover\"></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-esquerda\" id=\"e7\" style=\"left:23%;top:43.5%;width:34%;height:40%;z-index:3;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-133942-925770.png\" alt=\"\" style=\"object-fit:contain\"></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-esquerda\" id=\"e8\" style=\"left:23%;top:43.5%;width:34%;height:40%;z-index:4;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-133958-617b8e.png\" alt=\"\" style=\"object-fit:contain\"></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-esquerda\" id=\"e9\" style=\"left:23%;top:43.5%;width:34%;height:40%;z-index:5;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1.25;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1.25;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-134014-082953.png\" alt=\"\" style=\"object-fit:contain\"></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-zoom\" id=\"e10\" style=\"left:85%;top:2%;width:13%;height:26%;z-index:6;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-134539-9df56b.png\" alt=\"\" style=\"object-fit:contain\"></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-04 15:49:25', 'herdar'),
(392, 29, 18, 'Calçado de segurança', 'esquerda', 'cheio', 'solido', '#F2F5F9', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'herdar', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":92,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Proteção dos pés<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":13.2,\"w\":92,\"h\":10.5,\"html\":\"<h2>Calçado de segurança<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":25.9,\"w\":62.5,\"h\":6.6,\"html\":\"<p>É o equipamento de maior tempo de uso na jornada, e por isso o que mais sofre desgaste sem ser percebido. Reúne quatro características que o calçado comum não possui.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":130,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"abas\",\"dados\":{\"itens\":[{\"t\":\"Biqueira de proteção\",\"f\":\"1\",\"d\":\"Resiste ao impacto e à compressão provocados por queda de ferramenta, peça ou componente, e por passagem de carga sobre o pé. É o elemento que separa uma contusão de uma fratura em atividades de manutenção e movimentação.\"},{\"t\":\"Solado e aderência\",\"f\":\"2\",\"d\":\"O solado antiderrapante mantém a aderência em piso contaminado por óleo, graxa e água, condição habitual em áreas de manutenção e de lavagem. A resistência ao óleo e ao combustível impede que o composto se degrade, endureça e perca o desenho de tração, o que ocorre rapidamente em calçado comum.\"},{\"t\":\"Modelos específicos\",\"f\":\"3\",\"d\":\"Para intervenção em instalações elétricas existe calçado sem componente metálico, com característica isolante. Para atividades com risco de perfuração da sola há palmilha de aço ou composite. O modelo é definido pelo levantamento de riscos da atividade.\"},{\"t\":\"Higienização e guarda\",\"f\":\"4\",\"d\":\"Remova resíduo e umidade ao fim da jornada e deixe secar em local ventilado, longe de fonte direta de calor, que ressecca o couro e descola a solda do solado. Guarde em local seco. Solado liso, biqueira exposta, costura rompida ou cano rasgado são motivos de substituição imediata.\"}],\"guiado\":true},\"x\":3.5,\"y\":33.75,\"w\":64.5,\"h\":32.5,\"oculto\":true},{\"z\":1,\"s\":{\"fs\":110,\"anim\":\"subir\"},\"id\":\"e5\",\"t\":\"bloco\",\"bloco\":\"alerta\",\"dados\":{\"tipo\":\"dica\",\"titulo\":\"Calçado bem ajustado\",\"texto\":\"O calçado de segurança só protege de verdade quando está bem ajustado ao pé. Cadarços soltos ou mal amarrados deixam o pé instável e aumentam o risco de torção ou queda. Também é importante não modificar o calçado: cortar partes, remover a biqueira ou trocar a palmilha por uma que não seja adequada pode comprometer a proteção.\"},\"x\":3.5,\"y\":71.5,\"w\":62,\"h\":18.5,\"oculto\":true},{\"t\":\"imagem\",\"x\":18,\"y\":46.5,\"w\":34,\"h\":40,\"src\":\"img-20260831-135631-3e8b2d.png\",\"s\":{\"fit\":\"contain\",\"br\":14,\"sh\":0,\"anim\":\"zoom\"},\"id\":\"e6\",\"z\":2,\"oculto\":true},{\"t\":\"imagem\",\"x\":84.5,\"y\":4.899999999999999,\"w\":14.5,\"h\":21,\"src\":\"img-20260831-135648-201b03.png\",\"s\":{\"fit\":\"contain\",\"br\":14,\"sh\":0,\"anim\":\"zoom\"},\"id\":\"e7\",\"z\":3,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:92%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Proteção dos pés</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:13.2%;width:92%;height:10.5%;z-index:1;--trc-fs:1.46;\"><h2>Calçado de segurança</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:25.9%;width:62.5%;height:6.6%;z-index:1;\"><p>É o equipamento de maior tempo de uso na jornada, e por isso o que mais sofre desgaste sem ser percebido. Reúne quatro características que o calçado comum não possui.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:3.5%;top:33.75%;width:64.5%;height:32.5%;z-index:1;--trc-fs:1.3;\"><div class=\"trb trb-abas trb-guiado\" data-bloco=\"abas\" data-guiado=\"1\" data-apos=\"1\"><div class=\"trb-abas-barra\"><button type=\"button\" class=\"trb-aba\" data-i=\"0\" data-gi=\"0\" data-gf=\"1\">Biqueira de proteção</button><button type=\"button\" class=\"trb-aba\" data-i=\"1\" data-gi=\"1\" data-gf=\"2\">Solado e aderência</button><button type=\"button\" class=\"trb-aba\" data-i=\"2\" data-gi=\"2\" data-gf=\"3\">Modelos específicos</button><button type=\"button\" class=\"trb-aba\" data-i=\"3\" data-gi=\"3\" data-gf=\"4\">Higienização e guarda</button></div><div class=\"trb-abas-corpo\"><div class=\"trb-aba-painel\" data-i=\"0\">Resiste ao impacto e à compressão provocados por queda de ferramenta, peça ou componente, e por passagem de carga sobre o pé. É o elemento que separa uma contusão de uma fratura em atividades de manutenção e movimentação.</div><div class=\"trb-aba-painel\" data-i=\"1\">O solado antiderrapante mantém a aderência em piso contaminado por óleo, graxa e água, condição habitual em áreas de manutenção e de lavagem. A resistência ao óleo e ao combustível impede que o composto se degrade, endureça e perca o desenho de tração, o que ocorre rapidamente em calçado comum.</div><div class=\"trb-aba-painel\" data-i=\"2\">Para intervenção em instalações elétricas existe calçado sem componente metálico, com característica isolante. Para atividades com risco de perfuração da sola há palmilha de aço ou composite. O modelo é definido pelo levantamento de riscos da atividade.</div><div class=\"trb-aba-painel\" data-i=\"3\">Remova resíduo e umidade ao fim da jornada e deixe secar em local ventilado, longe de fonte direta de calor, que ressecca o couro e descola a solda do solado. Guarde em local seco. Solado liso, biqueira exposta, costura rompida ou cano rasgado são motivos de substituição imediata.</div><div class=\"trb-aba-vazio\">Abra as abas na ordem pedida pelo instrutor.</div></div></div></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e5\" style=\"left:3.5%;top:71.5%;width:62%;height:18.5%;z-index:1;--trc-fs:1.1;\"><div class=\"trb trb-alerta trb-alerta-dica\" data-bloco=\"alerta\"><i class=\"bi bi-lightbulb\"></i><div><b>Calçado bem ajustado</b><p>O calçado de segurança só protege de verdade quando está bem ajustado ao pé. Cadarços soltos ou mal amarrados deixam o pé instável e aumentam o risco de torção ou queda. Também é importante não modificar o calçado: cortar partes, remover a biqueira ou trocar a palmilha por uma que não seja adequada pode comprometer a proteção.</p></div></div></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-zoom\" id=\"e6\" style=\"left:18%;top:46.5%;width:34%;height:40%;z-index:2;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-135631-3e8b2d.png\" alt=\"\" style=\"object-fit:contain\"></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-zoom\" id=\"e7\" style=\"left:84.5%;top:4.899999999999999%;width:14.5%;height:21%;z-index:3;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-135648-201b03.png\" alt=\"\" style=\"object-fit:contain\"></div>\n</div>', '', '2026-08-31 07:33:43', '2026-08-31 14:11:58', 'herdar');
INSERT INTO `treinamentos_slides` (`id`, `apresentacao_id`, `ordem`, `titulo`, `transicao`, `layout`, `fundo_tipo`, `fundo_cor`, `fundo_cor2`, `fundo_angulo`, `fundo_imagem`, `fundo_escurecer`, `cor_texto`, `instrutor_visivel`, `instrutor_posicao`, `instrutor_lado_conteudo`, `instrutor_giro`, `instrutor_escala`, `instrutor_camera`, `conteudo_html`, `resumo`, `criado_em`, `atualizado_em`, `exigencia`) VALUES
(393, 29, 19, 'Protetor auricular', 'esquerda', 'cheio', 'solido', '#F2F5F9', '#F3F6FA', 160, NULL, 0, NULL, 0, 'direita', 'auto', 'herdar', 1.00, 'busto', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":92,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Proteção auditiva<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":13.2,\"w\":92,\"h\":10.5,\"html\":\"<h2>Protetor auricular<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":25.9,\"w\":92,\"h\":9.9,\"html\":\"<p>A audição é o único sistema tratado aqui em que o dano se acumula silenciosamente ao longo de anos, sem sinal de alerta. É também aquele em que o erro de colocação anula a proteção quase por completo.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":140,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"abas\",\"dados\":{\"itens\":[{\"t\":\"Por que a exposição preocupa\",\"f\":\"1\",\"d\":\"A perda auditiva induzida por ruído é progressiva, indolor e irreversível. Não há sintoma no momento da exposição, e quando a percepção chega o dano já está consolidado. Compressor, ferramenta pneumática, teste de motor, roçadeira e soprador são fontes comuns.\"},{\"t\":\"Protetor de inserção\",\"f\":\"2\",\"d\":\"O plugue precisa ser introduzido no canal auditivo, com a orelha tracionada para trás e para cima, até assentar. Apenas encostado na entrada, a atenuação real fica muito abaixo da nominal. Insira sempre com as mãos limpas, para não levar contaminante ao canal. Modelos reutilizáveis são lavados conforme a orientação e guardados no estojo.\"},{\"t\":\"Protetor tipo concha\",\"f\":\"3\",\"d\":\"A atenuação depende da almofada vedando contra a cabeça em todo o contorno. Haste de óculos, gorro, capuz e cabelo preso no caminho abrem frestas e derrubam o desempenho. Limpe as almofadas com pano úmido e sabão neutro, sem solvente, e substitua quando estiverem endurecidas ou ressecadas.\"},{\"t\":\"Tempo de uso\",\"f\":\"4\",\"d\":\"A proteção vale pelo tempo em que o equipamento está posicionado. Retirar o protetor por poucos minutos dentro da área para conversar, atender chamada ou beber água representa exposição integral nesse intervalo, sem qualquer atenuação.\"}],\"guiado\":true},\"x\":4,\"y\":34.5,\"w\":92,\"h\":35.5,\"oculto\":true},{\"z\":1,\"s\":{\"fs\":130,\"anim\":\"subir\"},\"id\":\"e5\",\"t\":\"bloco\",\"bloco\":\"alerta\",\"dados\":{\"tipo\":\"perigo\",\"titulo\":\"Nunca compartilhado\",\"texto\":\"Protetor auricular é item estritamente individual. O canal auditivo abriga flora própria, e o compartilhamento transmite otite externa e dermatite. Modelos descartáveis não são reutilizados entre jornadas, e os reutilizáveis têm estojo próprio, que também é individual.\"},\"x\":4.5,\"y\":72.5,\"w\":91.5,\"h\":19,\"oculto\":true},{\"t\":\"imagem\",\"x\":29,\"y\":62.5,\"w\":34,\"h\":31.5,\"src\":\"img-20260831-150803-b53e24.png\",\"s\":{\"fit\":\"contain\",\"br\":14,\"sh\":0,\"anim\":\"desfocar\"},\"id\":\"e6\",\"z\":2,\"oculto\":true},{\"t\":\"imagem\",\"x\":80.5,\"y\":8.2,\"w\":15.5,\"h\":15.5,\"src\":\"img-20260831-150856-eee91d.png\",\"s\":{\"fit\":\"contain\",\"br\":14,\"sh\":0,\"anim\":\"zoom\"},\"id\":\"e7\",\"z\":3,\"oculto\":true},{\"t\":\"imagem\",\"x\":29,\"y\":58.5,\"w\":34,\"h\":35.5,\"src\":\"img-20260831-151132-8000b2.png\",\"s\":{\"fit\":\"contain\",\"br\":14,\"sh\":0,\"anim\":\"desfocar\"},\"id\":\"e8\",\"z\":4,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:92%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Proteção auditiva</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:13.2%;width:92%;height:10.5%;z-index:1;--trc-fs:1.46;\"><h2>Protetor auricular</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:25.9%;width:92%;height:9.9%;z-index:1;\"><p>A audição é o único sistema tratado aqui em que o dano se acumula silenciosamente ao longo de anos, sem sinal de alerta. É também aquele em que o erro de colocação anula a proteção quase por completo.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:34.5%;width:92%;height:35.5%;z-index:1;--trc-fs:1.4;\"><div class=\"trb trb-abas trb-guiado\" data-bloco=\"abas\" data-guiado=\"1\" data-apos=\"1\"><div class=\"trb-abas-barra\"><button type=\"button\" class=\"trb-aba\" data-i=\"0\" data-gi=\"0\" data-gf=\"1\">Por que a exposição preocupa</button><button type=\"button\" class=\"trb-aba\" data-i=\"1\" data-gi=\"1\" data-gf=\"2\">Protetor de inserção</button><button type=\"button\" class=\"trb-aba\" data-i=\"2\" data-gi=\"2\" data-gf=\"3\">Protetor tipo concha</button><button type=\"button\" class=\"trb-aba\" data-i=\"3\" data-gi=\"3\" data-gf=\"4\">Tempo de uso</button></div><div class=\"trb-abas-corpo\"><div class=\"trb-aba-painel\" data-i=\"0\">A perda auditiva induzida por ruído é progressiva, indolor e irreversível. Não há sintoma no momento da exposição, e quando a percepção chega o dano já está consolidado. Compressor, ferramenta pneumática, teste de motor, roçadeira e soprador são fontes comuns.</div><div class=\"trb-aba-painel\" data-i=\"1\">O plugue precisa ser introduzido no canal auditivo, com a orelha tracionada para trás e para cima, até assentar. Apenas encostado na entrada, a atenuação real fica muito abaixo da nominal. Insira sempre com as mãos limpas, para não levar contaminante ao canal. Modelos reutilizáveis são lavados conforme a orientação e guardados no estojo.</div><div class=\"trb-aba-painel\" data-i=\"2\">A atenuação depende da almofada vedando contra a cabeça em todo o contorno. Haste de óculos, gorro, capuz e cabelo preso no caminho abrem frestas e derrubam o desempenho. Limpe as almofadas com pano úmido e sabão neutro, sem solvente, e substitua quando estiverem endurecidas ou ressecadas.</div><div class=\"trb-aba-painel\" data-i=\"3\">A proteção vale pelo tempo em que o equipamento está posicionado. Retirar o protetor por poucos minutos dentro da área para conversar, atender chamada ou beber água representa exposição integral nesse intervalo, sem qualquer atenuação.</div><div class=\"trb-aba-vazio\">Abra as abas na ordem pedida pelo instrutor.</div></div></div></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e5\" style=\"left:4.5%;top:72.5%;width:91.5%;height:19%;z-index:1;--trc-fs:1.3;\"><div class=\"trb trb-alerta trb-alerta-perigo\" data-bloco=\"alerta\"><i class=\"bi bi-shield-exclamation\"></i><div><b>Nunca compartilhado</b><p>Protetor auricular é item estritamente individual. O canal auditivo abriga flora própria, e o compartilhamento transmite otite externa e dermatite. Modelos descartáveis não são reutilizados entre jornadas, e os reutilizáveis têm estojo próprio, que também é individual.</p></div></div></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-desfocar\" id=\"e6\" style=\"left:29%;top:62.5%;width:34%;height:31.5%;z-index:2;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-150803-b53e24.png\" alt=\"\" style=\"object-fit:contain\"></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-zoom\" id=\"e7\" style=\"left:80.5%;top:8.2%;width:15.5%;height:15.5%;z-index:3;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-150856-eee91d.png\" alt=\"\" style=\"object-fit:contain\"></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-desfocar\" id=\"e8\" style=\"left:29%;top:58.5%;width:34%;height:35.5%;z-index:4;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-151132-8000b2.png\" alt=\"\" style=\"object-fit:contain\"></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-03 08:38:14', 'herdar'),
(394, 29, 20, 'Óculos e protetor facial', 'esquerda', 'esquerda', 'tema', '#FFFFFF', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'busto', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":58,\"h\":3,\"html\":\"<div class=\\\"trc-eyebrow\\\">Proteção dos olhos e da face<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":11.7,\"w\":58,\"h\":8,\"html\":\"<h2>Óculos e protetor facial<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":21.3,\"w\":58,\"h\":7.5,\"html\":\"<p>A lesão ocular é imediata e frequentemente definitiva. São três equipamentos com finalidades distintas, e conhecer a diferença evita a escolha errada.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":115,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"revelar\",\"dados\":{\"itens\":[{\"t\":\"Óculos de segurança\",\"f\":\"1\",\"d\":\"Lente e armação ensaiadas contra impacto de partículas projetadas em esmerilhamento, lixamento, corte, escovamento e uso de ar comprimido. Higienize com água e sabão neutro e seque com pano macio; papel e estopa riscam a lente e reduzem a visibilidade. Guarde em estojo, longe de peso e de calor, que deformam a armação.\"},{\"t\":\"Óculos ampla visão\",\"f\":\"2\",\"d\":\"Veda no contorno do olho e protege contra respingo de produto químico, de solução de bateria e de produto de limpeza aplicado sob pressão. Verifique a integridade do elástico e da vedação antes de usar, e substitua a lente ao primeiro sinal de opacidade permanente.\"},{\"t\":\"Protetor facial\",\"f\":\"3\",\"d\":\"Cobre toda a face contra projeção, respingo e calor radiante em esmerilhamento pesado, jateamento, manuseio de bateria e trabalho a quente. É usado sobre o óculos de segurança, e não em substituição a ele, porque a viseira não veda nas laterais nem protege contra partícula que contorna a face.\"}],\"guiado\":true},\"x\":4,\"y\":28.8,\"w\":61.5,\"h\":40.5,\"oculto\":true},{\"z\":1,\"s\":{\"fs\":115,\"anim\":\"subir\"},\"id\":\"e5\",\"t\":\"bloco\",\"bloco\":\"alerta\",\"dados\":{\"tipo\":\"atencao\",\"titulo\":\"Óculos de grau não substitui\",\"texto\":\"Óculos de grau comum não substitui óculos de segurança: a lente e a armação não são ensaiadas contra impacto e podem se fragmentar. Quem usa correção recebe modelo de sobrepor ou óculos de segurança com lente graduada.\"},\"x\":4,\"y\":75,\"w\":61.5,\"h\":19,\"oculto\":true},{\"t\":\"imagem\",\"x\":67.5,\"y\":29.299999999999997,\"w\":31.5,\"h\":40,\"src\":\"img-20260831-160217-ae4acb.png\",\"s\":{\"fit\":\"cover\",\"br\":14,\"sh\":0,\"anim\":\"subir\"},\"id\":\"e6\",\"z\":2,\"oculto\":true},{\"t\":\"imagem\",\"x\":81.5,\"y\":3,\"w\":16,\"h\":24,\"src\":\"img-20260831-160405-0587e4.png\",\"s\":{\"fit\":\"cover\",\"br\":14,\"sh\":0,\"anim\":\"zoom\"},\"id\":\"e7\",\"z\":3,\"oculto\":true},{\"t\":\"imagem\",\"x\":67,\"y\":29.299999999999997,\"w\":32,\"h\":40,\"src\":\"img-20260831-160922-048358.png\",\"s\":{\"fit\":\"cover\",\"br\":14,\"sh\":0,\"anim\":\"subir\"},\"id\":\"e8\",\"z\":4,\"oculto\":true},{\"t\":\"imagem\",\"x\":67.5,\"y\":29.299999999999997,\"w\":31.5,\"h\":49,\"src\":\"img-20260831-161027-2e055b.png\",\"s\":{\"fit\":\"cover\",\"br\":14,\"sh\":0,\"anim\":\"subir\"},\"id\":\"e9\",\"z\":5,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:58%;height:3%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Proteção dos olhos e da face</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:11.7%;width:58%;height:8%;z-index:1;--trc-fs:1.46;\"><h2>Óculos e protetor facial</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:21.3%;width:58%;height:7.5%;z-index:1;\"><p>A lesão ocular é imediata e frequentemente definitiva. São três equipamentos com finalidades distintas, e conhecer a diferença evita a escolha errada.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:28.8%;width:61.5%;height:40.5%;z-index:1;--trc-fs:1.15;\"><div class=\"trb trb-revelar trb-guiado\" data-bloco=\"revelar\" data-guiado=\"1\" data-apos=\"1\"><div class=\"trb-cards\"><button type=\"button\" class=\"trb-card\" data-bloco-ac=\"revelar\" data-gi=\"0\" data-gf=\"1\"><span class=\"trb-card-frente\"><span>Óculos de segurança</span><i class=\"bi bi-plus-circle\"></i></span><span class=\"trb-card-verso\">Lente e armação ensaiadas contra impacto de partículas projetadas em esmerilhamento, lixamento, corte, escovamento e uso de ar comprimido. Higienize com água e sabão neutro e seque com pano macio; papel e estopa riscam a lente e reduzem a visibilidade. Guarde em estojo, longe de peso e de calor, que deformam a armação.</span></button><button type=\"button\" class=\"trb-card\" data-bloco-ac=\"revelar\" data-gi=\"1\" data-gf=\"2\"><span class=\"trb-card-frente\"><span>Óculos ampla visão</span><i class=\"bi bi-plus-circle\"></i></span><span class=\"trb-card-verso\">Veda no contorno do olho e protege contra respingo de produto químico, de solução de bateria e de produto de limpeza aplicado sob pressão. Verifique a integridade do elástico e da vedação antes de usar, e substitua a lente ao primeiro sinal de opacidade permanente.</span></button><button type=\"button\" class=\"trb-card\" data-bloco-ac=\"revelar\" data-gi=\"2\" data-gf=\"3\"><span class=\"trb-card-frente\"><span>Protetor facial</span><i class=\"bi bi-plus-circle\"></i></span><span class=\"trb-card-verso\">Cobre toda a face contra projeção, respingo e calor radiante em esmerilhamento pesado, jateamento, manuseio de bateria e trabalho a quente. É usado sobre o óculos de segurança, e não em substituição a ele, porque a viseira não veda nas laterais nem protege contra partícula que contorna a face.</span></button></div></div></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e5\" style=\"left:4%;top:75%;width:61.5%;height:19%;z-index:1;--trc-fs:1.15;\"><div class=\"trb trb-alerta trb-alerta-atencao\" data-bloco=\"alerta\"><i class=\"bi bi-exclamation-triangle\"></i><div><b>Óculos de grau não substitui</b><p>Óculos de grau comum não substitui óculos de segurança: a lente e a armação não são ensaiadas contra impacto e podem se fragmentar. Quem usa correção recebe modelo de sobrepor ou óculos de segurança com lente graduada.</p></div></div></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-subir\" id=\"e6\" style=\"left:67.5%;top:29.299999999999997%;width:31.5%;height:40%;z-index:2;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-160217-ae4acb.png\" alt=\"\" style=\"object-fit:cover\"></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-zoom\" id=\"e7\" style=\"left:81.5%;top:3%;width:16%;height:24%;z-index:3;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-160405-0587e4.png\" alt=\"\" style=\"object-fit:cover\"></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-subir\" id=\"e8\" style=\"left:67%;top:29.299999999999997%;width:32%;height:40%;z-index:4;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-160922-048358.png\" alt=\"\" style=\"object-fit:cover\"></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-subir\" id=\"e9\" style=\"left:67.5%;top:29.299999999999997%;width:31.5%;height:49%;z-index:5;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-161027-2e055b.png\" alt=\"\" style=\"object-fit:cover\"></div>\n</div>', '', '2026-08-31 07:33:43', '2026-08-31 16:13:57', 'herdar'),
(395, 29, 21, 'Respiradores', 'esquerda', 'cheio', 'solido', '#F2F5F9', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'head', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":92,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Proteção respiratória<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":13.2,\"w\":92,\"h\":10.5,\"html\":\"<h2>Respiradores<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4.5,\"y\":25.9,\"w\":62,\"h\":6.6,\"html\":\"<p>Aplicável a atividades com aplicação de tinta, uso de desengraxante e solvente, lixamento e varrição a seco. É a família em que a diferença entre usar e usar corretamente é maior.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":125,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"abas\",\"dados\":{\"itens\":[{\"t\":\"Seleção do filtro\",\"f\":\"1\",\"d\":\"Cada filtro é fabricado para uma classe de contaminante. Filtro para material particulado não retém vapor orgânico, e filtro químico não substitui o de partículas. A seleção decorre da avaliação do agente presente na atividade, seja tinta, solvente, desengraxante, poeira de lixamento ou névoa de aplicação.\"},{\"t\":\"Vedação facial\",\"f\":\"2\",\"d\":\"O desempenho depende do contato contínuo entre o facial e a pele em todo o perímetro. Barba, costeleta longa, cicatriz saliente e armação de óculos na linha de vedação criam passagem para o ar contaminado, independentemente da qualidade do respirador. Verifique a vedação a cada colocação.\"},{\"t\":\"Validade e saturação\",\"f\":\"3\",\"d\":\"O filtro tem prazo próprio, que começa a correr na abertura da embalagem e continua mesmo com o respirador guardado. Anote a data de abertura. Não espere sentir odor ou sabor do produto para trocar: se você percebeu, o contaminante já passou pelo filtro.\"},{\"t\":\"Higienização e guarda\",\"f\":\"4\",\"d\":\"Limpe o facial com água e sabão neutro após o uso, sem solvente, e seque à sombra. Guarde em recipiente fechado, protegido de poeira, umidade e luz solar, com o filtro removido quando o fabricante orientar. Respirador guardado solto no armário perde vedação e acumula contaminante.\"}],\"guiado\":true},\"x\":4,\"y\":32.5,\"w\":92,\"h\":33.5,\"oculto\":true},{\"z\":1,\"s\":{\"fs\":130,\"anim\":\"subir\"},\"id\":\"e5\",\"t\":\"bloco\",\"bloco\":\"alerta\",\"dados\":{\"tipo\":\"atencao\",\"titulo\":\"Adaptação ao rosto é avaliada\",\"texto\":\"Respirador com facial de vedação exige avaliação prévia de adaptação ao rosto do usuário e acompanhamento de saúde ocupacional. A troca de modelo ou de tamanho não é escolha de preferência: ela decorre dessa avaliação e é solicitada ao setor de segurança do trabalho.\"},\"x\":4,\"y\":68,\"w\":62.5,\"h\":19,\"oculto\":true},{\"t\":\"imagem\",\"x\":86.5,\"y\":7.899999999999999,\"w\":11,\"h\":18,\"src\":\"img-20260831-164512-e023eb.png\",\"s\":{\"fit\":\"cover\",\"br\":14,\"sh\":0,\"anim\":\"zoom\"},\"id\":\"e6\",\"z\":2,\"oculto\":true},{\"t\":\"imagem\",\"x\":35.5,\"y\":54.5,\"w\":29,\"h\":40,\"src\":\"img-20260831-164807-2dc64a.png\",\"s\":{\"fit\":\"cover\",\"br\":14,\"sh\":0,\"anim\":\"zoom\"},\"id\":\"e7\",\"z\":3,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:92%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Proteção respiratória</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:13.2%;width:92%;height:10.5%;z-index:1;--trc-fs:1.46;\"><h2>Respiradores</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4.5%;top:25.9%;width:62%;height:6.6%;z-index:1;\"><p>Aplicável a atividades com aplicação de tinta, uso de desengraxante e solvente, lixamento e varrição a seco. É a família em que a diferença entre usar e usar corretamente é maior.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:32.5%;width:92%;height:33.5%;z-index:1;--trc-fs:1.25;\"><div class=\"trb trb-abas trb-guiado\" data-bloco=\"abas\" data-guiado=\"1\" data-apos=\"1\"><div class=\"trb-abas-barra\"><button type=\"button\" class=\"trb-aba\" data-i=\"0\" data-gi=\"0\" data-gf=\"1\">Seleção do filtro</button><button type=\"button\" class=\"trb-aba\" data-i=\"1\" data-gi=\"1\" data-gf=\"2\">Vedação facial</button><button type=\"button\" class=\"trb-aba\" data-i=\"2\" data-gi=\"2\" data-gf=\"3\">Validade e saturação</button><button type=\"button\" class=\"trb-aba\" data-i=\"3\" data-gi=\"3\" data-gf=\"4\">Higienização e guarda</button></div><div class=\"trb-abas-corpo\"><div class=\"trb-aba-painel\" data-i=\"0\">Cada filtro é fabricado para uma classe de contaminante. Filtro para material particulado não retém vapor orgânico, e filtro químico não substitui o de partículas. A seleção decorre da avaliação do agente presente na atividade, seja tinta, solvente, desengraxante, poeira de lixamento ou névoa de aplicação.</div><div class=\"trb-aba-painel\" data-i=\"1\">O desempenho depende do contato contínuo entre o facial e a pele em todo o perímetro. Barba, costeleta longa, cicatriz saliente e armação de óculos na linha de vedação criam passagem para o ar contaminado, independentemente da qualidade do respirador. Verifique a vedação a cada colocação.</div><div class=\"trb-aba-painel\" data-i=\"2\">O filtro tem prazo próprio, que começa a correr na abertura da embalagem e continua mesmo com o respirador guardado. Anote a data de abertura. Não espere sentir odor ou sabor do produto para trocar: se você percebeu, o contaminante já passou pelo filtro.</div><div class=\"trb-aba-painel\" data-i=\"3\">Limpe o facial com água e sabão neutro após o uso, sem solvente, e seque à sombra. Guarde em recipiente fechado, protegido de poeira, umidade e luz solar, com o filtro removido quando o fabricante orientar. Respirador guardado solto no armário perde vedação e acumula contaminante.</div><div class=\"trb-aba-vazio\">Abra as abas na ordem pedida pelo instrutor.</div></div></div></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e5\" style=\"left:4%;top:68%;width:62.5%;height:19%;z-index:1;--trc-fs:1.3;\"><div class=\"trb trb-alerta trb-alerta-atencao\" data-bloco=\"alerta\"><i class=\"bi bi-exclamation-triangle\"></i><div><b>Adaptação ao rosto é avaliada</b><p>Respirador com facial de vedação exige avaliação prévia de adaptação ao rosto do usuário e acompanhamento de saúde ocupacional. A troca de modelo ou de tamanho não é escolha de preferência: ela decorre dessa avaliação e é solicitada ao setor de segurança do trabalho.</p></div></div></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-zoom\" id=\"e6\" style=\"left:86.5%;top:7.899999999999999%;width:11%;height:18%;z-index:2;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-164512-e023eb.png\" alt=\"\" style=\"object-fit:cover\"></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-zoom\" id=\"e7\" style=\"left:35.5%;top:54.5%;width:29%;height:40%;z-index:3;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260831-164807-2dc64a.png\" alt=\"\" style=\"object-fit:cover\"></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-01 07:14:45', 'herdar'),
(396, 29, 22, 'Cabeça, tronco e membros', 'esquerda', 'esquerda', 'tema', '#FFFFFF', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'mid', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":58,\"h\":3.7,\"html\":\"<div class=\\\"trc-eyebrow\\\">Demais famílias<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":12.7,\"w\":58,\"h\":9.6,\"html\":\"<h2>Cabeça, tronco e membros<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":24.3,\"w\":58,\"h\":9,\"html\":\"<p>Reúne os equipamentos que protegem regiões amplas do corpo. São menos frequentes na rotina, e por isso costumam ser os mais negligenciados na inspeção.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":120,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"revelar\",\"dados\":{\"itens\":[{\"t\":\"Proteção da cabeça\",\"f\":\"1\",\"d\":\"Capacete contra impacto de objeto em queda, contra choque com estrutura fixa e, em modelos específicos, contra choque elétrico. A jugular ajustada é o que mantém o capacete posicionado no momento do impacto. Inspecione trincas e deformações, higienize com água e sabão neutro e guarde ao abrigo do sol, que degrada o casco.\"},{\"t\":\"Proteção do tronco\",\"f\":\"4\",\"d\":\"Avental, jaqueta e capa contra respingo de produto químico, calor radiante, projeção de partículas e umidade. Em atividade externa sob chuva ou próxima a tráfego, entram as vestimentas de alta visibilidade. Higienize separadamente do vestuário comum e substitua ao surgirem furos ou perda de refletividade.\"},{\"t\":\"Membros superiores e inferiores\",\"f\":\"5\",\"d\":\"Mangote e manga protegem o antebraço e o braço contra respingo, corte e calor. Perneira protege a perna contra projeção, respingo de solda e corte, e no caso da poda com motosserra o material é construído para travar a corrente antes de atingir o membro. Verifique fixação e integridade antes de cada uso.\"}],\"guiado\":true},\"x\":4,\"y\":35.3,\"w\":65.5,\"h\":57.7,\"oculto\":true},{\"t\":\"imagem\",\"x\":69.5,\"y\":39.5,\"w\":29.5,\"h\":40,\"src\":\"img-20260901-105130-d30550.png\",\"s\":{\"fit\":\"contain\",\"br\":14,\"sh\":0,\"anim\":\"descer\",\"x2\":66,\"y2\":40,\"w2\":34,\"h2\":40},\"id\":\"e5\",\"z\":2,\"oculto\":true},{\"t\":\"imagem\",\"x\":71.5,\"y\":39.5,\"w\":26,\"h\":24.5,\"src\":\"img-20260901-110444-ca6dca.png\",\"s\":{\"fit\":\"contain\",\"br\":14,\"sh\":0,\"anim\":\"descer\"},\"id\":\"e6\",\"z\":3,\"oculto\":true},{\"t\":\"imagem\",\"x\":74,\"y\":64,\"w\":22,\"h\":21,\"src\":\"img-20260901-110522-effcd8.png\",\"s\":{\"fit\":\"contain\",\"br\":14,\"sh\":0,\"anim\":\"subir\"},\"id\":\"e7\",\"z\":4,\"oculto\":true},{\"t\":\"imagem\",\"x\":82.5,\"y\":2.8000000000000007,\"w\":15,\"h\":21.5,\"src\":\"img-20260901-112641-9af0e2.png\",\"s\":{\"fit\":\"contain\",\"br\":14,\"sh\":0,\"anim\":\"direita\"},\"id\":\"e8\",\"z\":5,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:58%;height:3.7%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Demais famílias</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:12.7%;width:58%;height:9.6%;z-index:1;--trc-fs:1.46;\"><h2>Cabeça, tronco e membros</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:24.3%;width:58%;height:9%;z-index:1;\"><p>Reúne os equipamentos que protegem regiões amplas do corpo. São menos frequentes na rotina, e por isso costumam ser os mais negligenciados na inspeção.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:35.3%;width:65.5%;height:57.7%;z-index:1;--trc-fs:1.2;\"><div class=\"trb trb-revelar trb-guiado\" data-bloco=\"revelar\" data-guiado=\"1\" data-apos=\"1\"><div class=\"trb-cards\"><button type=\"button\" class=\"trb-card\" data-bloco-ac=\"revelar\" data-gi=\"0\" data-gf=\"1\"><span class=\"trb-card-frente\"><span>Proteção da cabeça</span><i class=\"bi bi-plus-circle\"></i></span><span class=\"trb-card-verso\">Capacete contra impacto de objeto em queda, contra choque com estrutura fixa e, em modelos específicos, contra choque elétrico. A jugular ajustada é o que mantém o capacete posicionado no momento do impacto. Inspecione trincas e deformações, higienize com água e sabão neutro e guarde ao abrigo do sol, que degrada o casco.</span></button><button type=\"button\" class=\"trb-card\" data-bloco-ac=\"revelar\" data-gi=\"1\" data-gf=\"4\"><span class=\"trb-card-frente\"><span>Proteção do tronco</span><i class=\"bi bi-plus-circle\"></i></span><span class=\"trb-card-verso\">Avental, jaqueta e capa contra respingo de produto químico, calor radiante, projeção de partículas e umidade. Em atividade externa sob chuva ou próxima a tráfego, entram as vestimentas de alta visibilidade. Higienize separadamente do vestuário comum e substitua ao surgirem furos ou perda de refletividade.</span></button><button type=\"button\" class=\"trb-card\" data-bloco-ac=\"revelar\" data-gi=\"2\" data-gf=\"5\"><span class=\"trb-card-frente\"><span>Membros superiores e inferiores</span><i class=\"bi bi-plus-circle\"></i></span><span class=\"trb-card-verso\">Mangote e manga protegem o antebraço e o braço contra respingo, corte e calor. Perneira protege a perna contra projeção, respingo de solda e corte, e no caso da poda com motosserra o material é construído para travar a corrente antes de atingir o membro. Verifique fixação e integridade antes de cada uso.</span></button></div></div></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-descer trc-movel\" id=\"e5\" style=\"left:69.5%;top:39.5%;width:29.5%;height:40%;z-index:2;border-radius:14px;border-radius:1.67cqw;transform-origin:0 0;--trc-base:none;--trc-mov:translate(-11.86%,1.25%) scale(1.15,1);--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260901-105130-d30550.png\" alt=\"\" style=\"object-fit:contain\"></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-descer\" id=\"e6\" style=\"left:71.5%;top:39.5%;width:26%;height:24.5%;z-index:3;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260901-110444-ca6dca.png\" alt=\"\" style=\"object-fit:contain\"></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-subir\" id=\"e7\" style=\"left:74%;top:64%;width:22%;height:21%;z-index:4;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260901-110522-effcd8.png\" alt=\"\" style=\"object-fit:contain\"></div>\n<div class=\"trc-el trc-imagem nv-oculto trv-anim-direita\" id=\"e8\" style=\"left:82.5%;top:2.8000000000000007%;width:15%;height:21.5%;z-index:5;border-radius:14px;border-radius:1.67cqw;--trc-img-zoom:1;--trc-img-giro:0deg;--trc-img-x:50%;--trc-img-y:50%;--trc-img-zoom2:1;--trc-img-giro2:0deg;--trc-img-x2:50%;--trc-img-y2:50%;--trc-img-dur:1.1s;\"><img src=\"/instrucoes/treinamentos/midia.php?a=29&amp;f=img-20260901-112641-9af0e2.png\" alt=\"\" style=\"object-fit:contain\"></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-03 08:27:08', 'herdar'),
(397, 29, 23, 'Proteção contra quedas', 'esquerda', 'cheio', 'solido', '#F2F5F9', '#F3F6FA', 160, NULL, 0, NULL, 0, 'direita', 'auto', 'herdar', 1.00, 'herdar', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":92,\"h\":3.1,\"html\":\"<div class=\\\"trc-eyebrow\\\">Trabalho em altura<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":11.8,\"w\":92,\"h\":8.3,\"html\":\"<h2>Proteção contra quedas<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":21.9,\"w\":92,\"h\":5.2,\"html\":\"<p>Chegamos ao último tema do módulo que é uma família que demanda cuidado redobrado e o uso correto dos EPIs específicos para essa função.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":110,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"passos\",\"dados\":{\"itens\":[{\"t\":\"Quando é exigida\",\"f\":\"1\",\"d\":\"Em toda atividade com risco de queda com diferença de nível, incluindo trabalho sobre escada, plataforma, cobertura e poda em altura. A exigência não decorre da altura isolada, mas da existência do risco de queda e da ausência de proteção coletiva capaz de eliminá-lo.\"},{\"t\":\"O que compõe o sistema\",\"f\":\"2\",\"d\":\"Cinturão tipo paraquedista, talabarte com absorvedor de energia ou trava-quedas, e ponto de ancoragem previsto e dimensionado em projeto. Os três formam um sistema: nenhum deles protege isoladamente, e a substituição de qualquer parte por item não previsto compromete o conjunto.\"},{\"t\":\"Inspeção antes de cada uso\",\"f\":\"3\",\"d\":\"Verifique fitas quanto a cortes, desgaste, queimadura e fios rompidos; costuras quanto a rompimento; fivelas, mosquetões e travas quanto a deformação, trinca e funcionamento da trava de segurança. Qualquer alteração retira o conjunto de serviço na hora.\"},{\"t\":\"Guarda e destinação\",\"f\":\"4\",\"d\":\"Guarde pendurado, em local seco, ventilado e ao abrigo de luz solar, calor, óleo e produto químico. Após uma queda em que o sistema tenha sido utilizado, o conjunto é retirado de uso definitivamente e descartado, ainda que aparente estar íntegro: o material já absorveu a energia e não repetirá o desempenho.\"}],\"guiado\":true},\"x\":4,\"y\":27.099999999999998,\"w\":92,\"h\":51,\"oculto\":true},{\"z\":1,\"s\":{\"fs\":115,\"anim\":\"subir\"},\"id\":\"e5\",\"t\":\"bloco\",\"bloco\":\"alerta\",\"dados\":{\"tipo\":\"atencao\",\"titulo\":\"Exige capacitação específica\",\"texto\":\"O uso do sistema de proteção contra quedas pressupõe capacitação específica de trabalho em altura, com conteúdo e periodicidade próprios, além desta capacitação sobre EPI.\"},\"x\":4,\"y\":78.1,\"w\":92,\"h\":12.5,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:92%;height:3.1%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Trabalho em altura</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:11.8%;width:92%;height:8.3%;z-index:1;--trc-fs:1.46;\"><h2>Proteção contra quedas</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:21.9%;width:92%;height:5.2%;z-index:1;\"><p>Chegamos ao último tema do módulo que é uma família que demanda cuidado redobrado e o uso correto dos EPIs específicos para essa função.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:27.099999999999998%;width:92%;height:51%;z-index:1;--trc-fs:1.1;\"><div class=\"trb trb-passos trb-guiado\" data-bloco=\"passos\" data-guiado=\"1\" data-apos=\"1\"><ol class=\"trb-passos-lista\"><li class=\"trb-passo\" data-gi=\"0\" data-gf=\"1\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">1</span><span class=\"trb-passo-corpo\"><b>Quando é exigida</b><small>Em toda atividade com risco de queda com diferença de nível, incluindo trabalho sobre escada, plataforma, cobertura e poda em altura. A exigência não decorre da altura isolada, mas da existência do risco de queda e da ausência de proteção coletiva capaz de eliminá-lo.</small></span></li><li class=\"trb-passo\" data-gi=\"1\" data-gf=\"2\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">2</span><span class=\"trb-passo-corpo\"><b>O que compõe o sistema</b><small>Cinturão tipo paraquedista, talabarte com absorvedor de energia ou trava-quedas, e ponto de ancoragem previsto e dimensionado em projeto. Os três formam um sistema: nenhum deles protege isoladamente, e a substituição de qualquer parte por item não previsto compromete o conjunto.</small></span></li><li class=\"trb-passo\" data-gi=\"2\" data-gf=\"3\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">3</span><span class=\"trb-passo-corpo\"><b>Inspeção antes de cada uso</b><small>Verifique fitas quanto a cortes, desgaste, queimadura e fios rompidos; costuras quanto a rompimento; fivelas, mosquetões e travas quanto a deformação, trinca e funcionamento da trava de segurança. Qualquer alteração retira o conjunto de serviço na hora.</small></span></li><li class=\"trb-passo\" data-gi=\"3\" data-gf=\"4\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">4</span><span class=\"trb-passo-corpo\"><b>Guarda e destinação</b><small>Guarde pendurado, em local seco, ventilado e ao abrigo de luz solar, calor, óleo e produto químico. Após uma queda em que o sistema tenha sido utilizado, o conjunto é retirado de uso definitivamente e descartado, ainda que aparente estar íntegro: o material já absorveu a energia e não repetirá o desempenho.</small></span></li></ol></div></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e5\" style=\"left:4%;top:78.1%;width:92%;height:12.5%;z-index:1;--trc-fs:1.15;\"><div class=\"trb trb-alerta trb-alerta-atencao\" data-bloco=\"alerta\"><i class=\"bi bi-exclamation-triangle\"></i><div><b>Exige capacitação específica</b><p>O uso do sistema de proteção contra quedas pressupõe capacitação específica de trabalho em altura, com conteúdo e periodicidade próprios, além desta capacitação sobre EPI.</p></div></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-01 11:52:00', 'herdar'),
(398, 29, 24, 'Verificação 3', 'zoom', 'cheio', 'solido', '#F2F5F9', '#F3F6FA', 160, NULL, 0, NULL, 0, 'direita', 'auto', 'herdar', 1.00, 'herdar', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":92,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Verificação de aprendizagem 3<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":13.2,\"w\":92,\"h\":10.5,\"html\":\"<h2>Analise a situação<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":115,\"anim\":\"subir\"},\"id\":\"e3\",\"t\":\"bloco\",\"bloco\":\"quiz\",\"dados\":{\"pergunta\":\"Em uma atividade de lavagem de peças com desengraxante, seguida de montagem, qual é a composição correta da proteção das mãos?\",\"opcoes\":[{\"t\":\"Creme protetor antes de iniciar, luva para agente químico na lavagem e luva para risco mecânico na montagem, com reaplicação do creme a cada troca\",\"ok\":true},{\"t\":\"A mesma luva nas duas etapas, desde que possua Certificado de Aprovação válido\",\"ok\":false},{\"t\":\"Apenas creme protetor, por se tratar de contato de curta duração\",\"ok\":false},{\"t\":\"Luva para agente químico nas duas etapas, por ser a de maior resistência\",\"ok\":false}],\"feedback\":\"O agente muda no decorrer da atividade, e a luva acompanha essa mudança. O creme protetor antecede as duas etapas e é reaplicado sempre que a luva é retirada, porque a película sai com a transpiração e com a higienização das mãos.\",\"varias\":false},\"x\":4,\"y\":23.7,\"w\":92,\"h\":69,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:92%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Verificação de aprendizagem 3</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:13.2%;width:92%;height:10.5%;z-index:1;--trc-fs:1.46;\"><h2>Analise a situação</h2></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e3\" style=\"left:4%;top:23.7%;width:92%;height:69%;z-index:1;--trc-fs:1.15;\"><div class=\"trb trb-quiz\" data-bloco=\"quiz\"><div class=\"trb-quiz-topo\"><i class=\"bi bi-patch-question\"></i><span>Pergunta</span></div><p class=\"trb-quiz-pergunta\">Em uma atividade de lavagem de peças com desengraxante, seguida de montagem, qual é a composição correta da proteção das mãos?</p><div class=\"trb-quiz-ops\"><button type=\"button\" class=\"trb-quiz-op\" data-i=\"0\" data-ok=\"1\"><span class=\"trb-quiz-letra\">A</span><span class=\"trb-quiz-txt\">Creme protetor antes de iniciar, luva para agente químico na lavagem e luva para risco mecânico na montagem, com reaplicação do creme a cada troca</span><i class=\"bi trb-quiz-icone\"></i></button><button type=\"button\" class=\"trb-quiz-op\" data-i=\"1\" data-ok=\"0\"><span class=\"trb-quiz-letra\">B</span><span class=\"trb-quiz-txt\">A mesma luva nas duas etapas, desde que possua Certificado de Aprovação válido</span><i class=\"bi trb-quiz-icone\"></i></button><button type=\"button\" class=\"trb-quiz-op\" data-i=\"2\" data-ok=\"0\"><span class=\"trb-quiz-letra\">C</span><span class=\"trb-quiz-txt\">Apenas creme protetor, por se tratar de contato de curta duração</span><i class=\"bi trb-quiz-icone\"></i></button><button type=\"button\" class=\"trb-quiz-op\" data-i=\"3\" data-ok=\"0\"><span class=\"trb-quiz-letra\">D</span><span class=\"trb-quiz-txt\">Luva para agente químico nas duas etapas, por ser a de maior resistência</span><i class=\"bi trb-quiz-icone\"></i></button></div><div class=\"trb-quiz-feedback\"><i class=\"bi bi-info-circle\"></i><span>O agente muda no decorrer da atividade, e a luva acompanha essa mudança. O creme protetor antecede as duas etapas e é reaplicado sempre que a luva é retirada, porque a película sai com a transpiração e com a higienização das mãos.</span></div></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-01 11:53:14', 'quiz'),
(399, 29, 25, 'Módulo 04', 'cima', 'esquerda', 'gradiente', '#08243F', '#134E86', 160, NULL, 0, '#FFFFFF', 1, 'direita', 'auto', 'herdar', 1.00, 'busto', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":144,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":33,\"w\":58,\"h\":6,\"html\":\"<div class=\\\"trc-eyebrow\\\" style=\\\"color:#7FC4FF\\\">Módulo 04<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":180,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":41,\"w\":58,\"h\":18,\"html\":\"<h2>Uso, conservação e substituição<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":104,\"anim\":\"subir\"},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":60.5,\"w\":58,\"h\":6.9,\"html\":\"<p>Os deveres do trabalhador, o tempo de exposição, a rotina de higienização e guarda e o procedimento de comunicação e troca.<\\/p>\",\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:33%;width:58%;height:6%;z-index:1;--trc-fs:1.44;\"><div class=\"trc-eyebrow\" style=\"color:#7FC4FF\">Módulo 04</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:41%;width:58%;height:18%;z-index:1;--trc-fs:1.8;\"><h2>Uso, conservação e substituição</h2></div>\n<div class=\"trc-el trc-texto nv-oculto trv-anim-subir\" id=\"e3\" style=\"left:4%;top:60.5%;width:58%;height:6.9%;z-index:1;--trc-fs:1.04;\"><p>Os deveres do trabalhador, o tempo de exposição, a rotina de higienização e guarda e o procedimento de comunicação e troca.</p></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-01 11:54:18', 'nenhuma'),
(400, 29, 26, 'O que compete ao trabalhador', 'esquerda', 'esquerda', 'tema', '#FFFFFF', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'busto', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":58,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Responsabilidades<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":13.2,\"w\":58,\"h\":10.5,\"html\":\"<h2>O que compete ao trabalhador<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":22,\"w\":58,\"h\":13.2,\"html\":\"<p>São cinco deveres, previstos na norma e reforçados pelo artigo 158 da Consolidação das Leis do Trabalho. Todos convergem para o mesmo objetivo: manter a proteção operante enquanto houver exposição.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":140,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"checklist\",\"dados\":{\"itens\":[{\"t\":\"Utilizar o equipamento durante todo o período de exposição ao risco\",\"f\":\"1\"},{\"t\":\"Empregá-lo apenas para a finalidade a que se destina\",\"f\":\"4\"},{\"t\":\"Responsabilizar-se pela guarda e pela conservação do que recebeu\",\"f\":\"8\"},{\"t\":\"Comunicar qualquer alteração que o torne impróprio para uso\",\"f\":\"12\"},{\"t\":\"Cumprir as orientações recebidas sobre o uso correto\",\"f\":\"16\"}],\"guiado\":true,\"titulo\":\"Marque conforme acompanha a leitura\"},\"x\":4,\"y\":29.5,\"w\":63,\"h\":51,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:58%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Responsabilidades</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:13.2%;width:58%;height:10.5%;z-index:1;--trc-fs:1.46;\"><h2>O que compete ao trabalhador</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:22%;width:58%;height:13.2%;z-index:1;\"><p>São cinco deveres, previstos na norma e reforçados pelo artigo 158 da Consolidação das Leis do Trabalho. Todos convergem para o mesmo objetivo: manter a proteção operante enquanto houver exposição.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:29.5%;width:63%;height:51%;z-index:1;--trc-fs:1.4;\"><div class=\"trb trb-checklist trb-guiado\" data-bloco=\"checklist\" data-guiado=\"1\" data-apos=\"1\"><div class=\"trb-titulo\">Marque conforme acompanha a leitura</div><div class=\"trb-checks\"><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"0\" data-gf=\"1\"><i class=\"bi bi-square\"></i><span>Utilizar o equipamento durante todo o período de exposição ao risco</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"1\" data-gf=\"4\"><i class=\"bi bi-square\"></i><span>Empregá-lo apenas para a finalidade a que se destina</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"2\" data-gf=\"8\"><i class=\"bi bi-square\"></i><span>Responsabilizar-se pela guarda e pela conservação do que recebeu</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"3\" data-gf=\"12\"><i class=\"bi bi-square\"></i><span>Comunicar qualquer alteração que o torne impróprio para uso</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"4\" data-gf=\"16\"><i class=\"bi bi-square\"></i><span>Cumprir as orientações recebidas sobre o uso correto</span></button></div></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-01 14:16:13', 'herdar');
INSERT INTO `treinamentos_slides` (`id`, `apresentacao_id`, `ordem`, `titulo`, `transicao`, `layout`, `fundo_tipo`, `fundo_cor`, `fundo_cor2`, `fundo_angulo`, `fundo_imagem`, `fundo_escurecer`, `cor_texto`, `instrutor_visivel`, `instrutor_posicao`, `instrutor_lado_conteudo`, `instrutor_giro`, `instrutor_escala`, `instrutor_camera`, `conteudo_html`, `resumo`, `criado_em`, `atualizado_em`, `exigencia`) VALUES
(401, 29, 27, 'O tempo de exposição', 'esquerda', 'cheio', 'solido', '#F2F5F9', '#F3F6FA', 160, NULL, 0, NULL, 0, 'direita', 'auto', 'herdar', 1.00, 'herdar', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":92,\"h\":3.6,\"html\":\"<div class=\\\"trc-eyebrow\\\">Uso correto<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":12.6,\"w\":92,\"h\":9.5,\"html\":\"<h2>O tempo de exposição<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":24.1,\"w\":92,\"h\":6,\"html\":\"<p>Os dois primeiros deveres se traduzem, na prática, em quatro situações recorrentes. Vale examinar cada uma com o argumento correspondente.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":140,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"revelar\",\"dados\":{\"itens\":[{\"t\":\"A atividade é rápida\",\"f\":\"1\",\"d\":\"A exposição se instala no primeiro instante de contato. A duração reduzida não altera a energia do impacto, o nível de pressão sonora nem a concentração do agente químico presente. O que muda é apenas a probabilidade de o evento ocorrer, e ela nunca é zero.\"},{\"t\":\"O equipamento incomoda\",\"f\":\"2\",\"d\":\"Desconforto persistente costuma indicar dimensionamento inadequado, e isso tem tratamento previsto: solicitação de outro modelo ou de outro tamanho. Adaptar por conta própria, com corte, furo, fita ou espuma, anula o ensaio e a validade do certificado para aquele item.\"},{\"t\":\"Esqueci o equipamento\",\"f\":\"3\",\"d\":\"A atividade não é iniciada. Providencie o equipamento ou comunique a liderança para que ele seja disponibilizado. Iniciar sem transfere integralmente o risco residual para o seu corpo, sem qualquer barreira intermediária.\"},{\"t\":\"Sempre trabalhei assim\",\"f\":\"4\",\"d\":\"Tempo de exposição sem ocorrência não constitui evidência de segurança. O risco permanece com a mesma intensidade, e o histórico anterior não reduz a probabilidade do próximo evento. Acidente é resultado de exposição, não de estatística pessoal.\"}],\"guiado\":true},\"x\":4,\"y\":28.5,\"w\":92,\"h\":48.5,\"oculto\":true},{\"z\":1,\"s\":{\"fs\":125,\"anim\":\"subir\"},\"id\":\"e5\",\"t\":\"bloco\",\"bloco\":\"alerta\",\"dados\":{\"tipo\":\"perigo\",\"titulo\":\"A proteção vale pelo tempo de uso\",\"texto\":\"O equipamento não protege pelo fato de estar em sua posse. Ele protege enquanto está vestido, ajustado e íntegro. Fora dessa condição, a exposição é idêntica à de quem não recebeu nada.\"},\"x\":4,\"y\":78.5,\"w\":68,\"h\":14,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:92%;height:3.6%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Uso correto</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:12.6%;width:92%;height:9.5%;z-index:1;--trc-fs:1.46;\"><h2>O tempo de exposição</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4%;top:24.1%;width:92%;height:6%;z-index:1;\"><p>Os dois primeiros deveres se traduzem, na prática, em quatro situações recorrentes. Vale examinar cada uma com o argumento correspondente.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:28.5%;width:92%;height:48.5%;z-index:1;--trc-fs:1.4;\"><div class=\"trb trb-revelar trb-guiado\" data-bloco=\"revelar\" data-guiado=\"1\" data-apos=\"1\"><div class=\"trb-cards\"><button type=\"button\" class=\"trb-card\" data-bloco-ac=\"revelar\" data-gi=\"0\" data-gf=\"1\"><span class=\"trb-card-frente\"><span>A atividade é rápida</span><i class=\"bi bi-plus-circle\"></i></span><span class=\"trb-card-verso\">A exposição se instala no primeiro instante de contato. A duração reduzida não altera a energia do impacto, o nível de pressão sonora nem a concentração do agente químico presente. O que muda é apenas a probabilidade de o evento ocorrer, e ela nunca é zero.</span></button><button type=\"button\" class=\"trb-card\" data-bloco-ac=\"revelar\" data-gi=\"1\" data-gf=\"2\"><span class=\"trb-card-frente\"><span>O equipamento incomoda</span><i class=\"bi bi-plus-circle\"></i></span><span class=\"trb-card-verso\">Desconforto persistente costuma indicar dimensionamento inadequado, e isso tem tratamento previsto: solicitação de outro modelo ou de outro tamanho. Adaptar por conta própria, com corte, furo, fita ou espuma, anula o ensaio e a validade do certificado para aquele item.</span></button><button type=\"button\" class=\"trb-card\" data-bloco-ac=\"revelar\" data-gi=\"2\" data-gf=\"3\"><span class=\"trb-card-frente\"><span>Esqueci o equipamento</span><i class=\"bi bi-plus-circle\"></i></span><span class=\"trb-card-verso\">A atividade não é iniciada. Providencie o equipamento ou comunique a liderança para que ele seja disponibilizado. Iniciar sem transfere integralmente o risco residual para o seu corpo, sem qualquer barreira intermediária.</span></button><button type=\"button\" class=\"trb-card\" data-bloco-ac=\"revelar\" data-gi=\"3\" data-gf=\"4\"><span class=\"trb-card-frente\"><span>Sempre trabalhei assim</span><i class=\"bi bi-plus-circle\"></i></span><span class=\"trb-card-verso\">Tempo de exposição sem ocorrência não constitui evidência de segurança. O risco permanece com a mesma intensidade, e o histórico anterior não reduz a probabilidade do próximo evento. Acidente é resultado de exposição, não de estatística pessoal.</span></button></div></div></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e5\" style=\"left:4%;top:78.5%;width:68%;height:14%;z-index:1;--trc-fs:1.25;\"><div class=\"trb trb-alerta trb-alerta-perigo\" data-bloco=\"alerta\"><i class=\"bi bi-shield-exclamation\"></i><div><b>A proteção vale pelo tempo de uso</b><p>O equipamento não protege pelo fato de estar em sua posse. Ele protege enquanto está vestido, ajustado e íntegro. Fora dessa condição, a exposição é idêntica à de quem não recebeu nada.</p></div></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-09 14:46:51', 'herdar'),
(402, 29, 28, 'A rotina de cada jornada', 'esquerda', 'cheio', 'solido', '#F2F5F9', '#F3F6FA', 160, NULL, 0, NULL, 1, 'centro', 'auto', 'herdar', 1.00, 'head', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":92,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Conservação<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":13.2,\"w\":92,\"h\":10.5,\"html\":\"<h2>A rotina de cada jornada<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4,\"y\":23.7,\"w\":92,\"h\":6.6,\"html\":\"<p>A guarda e a conservação são deveres do trabalhador. Não se confundem com a manutenção periódica, que é responsabilidade da empresa, e seguem quatro momentos ao longo do dia.<\\/p>\",\"oculto\":true},{\"z\":1,\"s\":{\"fs\":140,\"anim\":\"subir\",\"pad\":0},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"linhaTempo\",\"dados\":{\"itens\":[{\"t\":\"Antes de iniciar\",\"f\":\"1\",\"d\":\"Inspeção visual de cada item: trincas, cortes, furos, deformação, costura rompida, elástico ressecado, almofada endurecida, filtro fora do prazo e certificado ilegível. Leva menos de um minuto e é o último filtro entre o equipamento certificado e o equipamento que ainda protege.\"},{\"t\":\"Durante a jornada\",\"f\":\"2\",\"d\":\"Uso contínuo enquanto durar a exposição, sem adaptação e sem compartilhamento. Reaplicação do creme protetor a cada higienização das mãos. Verificação do ajuste após qualquer movimento que possa ter deslocado o equipamento.\"},{\"t\":\"Ao encerrar\",\"f\":\"3\",\"d\":\"Higienize conforme a orientação do fabricante, com água e sabão neutro na maior parte dos casos e sem solvente. Seque à sombra, em local ventilado, e nunca sobre fonte de calor. Equipamento guardado úmido perde resistência, prolifera fungo e gera odor.\"},{\"t\":\"Ao guardar\",\"f\":\"4\",\"d\":\"Local limpo, seco e ventilado, ao abrigo de luz solar direta, calor, óleo e produto químico. Evite caixa de ferramenta com peças sobre o equipamento, bolso de vestimenta, painel de veículo e armário sem circulação de ar: calor e compressão deformam o item de forma silenciosa e progressiva.\"}],\"guiado\":true,\"guiaAuto\":true},\"x\":4,\"y\":32.6,\"w\":92,\"h\":60,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:92%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Conservação</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:13.2%;width:92%;height:10.5%;z-index:1;--trc-fs:1.46;\"><h2>A rotina de cada jornada</h2></div>\n<div class=\"trc-el trc-texto nv-oculto\" id=\"e3\" style=\"left:4%;top:23.7%;width:92%;height:6.6%;z-index:1;\"><p>A guarda e a conservação são deveres do trabalhador. Não se confundem com a manutenção periódica, que é responsabilidade da empresa, e seguem quatro momentos ao longo do dia.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:32.6%;width:92%;height:60%;z-index:1;--trc-fs:1.4;\"><div class=\"trb trb-linha-tempo trb-guiado\" data-bloco=\"linhaTempo\" data-guiado=\"1\" data-apos=\"1\" data-gauto=\"1\"><ul><li class=\"trb-marco\" data-gi=\"0\" data-gf=\"1\" role=\"button\" tabindex=\"0\"><span class=\"trb-marco-ponto\"></span><b>Antes de iniciar</b><small>Inspeção visual de cada item: trincas, cortes, furos, deformação, costura rompida, elástico ressecado, almofada endurecida, filtro fora do prazo e certificado ilegível. Leva menos de um minuto e é o último filtro entre o equipamento certificado e o equipamento que ainda protege.</small></li><li class=\"trb-marco\" data-gi=\"1\" data-gf=\"2\" role=\"button\" tabindex=\"0\"><span class=\"trb-marco-ponto\"></span><b>Durante a jornada</b><small>Uso contínuo enquanto durar a exposição, sem adaptação e sem compartilhamento. Reaplicação do creme protetor a cada higienização das mãos. Verificação do ajuste após qualquer movimento que possa ter deslocado o equipamento.</small></li><li class=\"trb-marco\" data-gi=\"2\" data-gf=\"3\" role=\"button\" tabindex=\"0\"><span class=\"trb-marco-ponto\"></span><b>Ao encerrar</b><small>Higienize conforme a orientação do fabricante, com água e sabão neutro na maior parte dos casos e sem solvente. Seque à sombra, em local ventilado, e nunca sobre fonte de calor. Equipamento guardado úmido perde resistência, prolifera fungo e gera odor.</small></li><li class=\"trb-marco\" data-gi=\"3\" data-gf=\"4\" role=\"button\" tabindex=\"0\"><span class=\"trb-marco-ponto\"></span><b>Ao guardar</b><small>Local limpo, seco e ventilado, ao abrigo de luz solar direta, calor, óleo e produto químico. Evite caixa de ferramenta com peças sobre o equipamento, bolso de vestimenta, painel de veículo e armário sem circulação de ar: calor e compressão deformam o item de forma silenciosa e progressiva.</small></li></ul></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-02 08:40:57', 'herdar'),
(403, 29, 29, 'Quando comunicar e como trocar', 'esquerda', 'esquerda', 'tema', '#FFFFFF', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'busto', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":58,\"h\":2.7,\"html\":\"<div class=\\\"trc-eyebrow\\\">Substituição<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":11.2,\"w\":58,\"h\":7.1,\"html\":\"<h2>Quando comunicar e como trocar<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":100},\"id\":\"e3\",\"t\":\"texto\",\"x\":4.5,\"y\":19.5,\"w\":63,\"h\":6.7,\"html\":\"<p>A norma organiza esse fluxo em quatro etapas, alternando responsabilidade entre você e a empresa. Conhecê-lo evita o uso prolongado de equipamento que já deixou de proteger.<\\/p>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":115,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"passos\",\"dados\":{\"itens\":[{\"t\":\"Identificação\",\"f\":\"1\",\"d\":\"Comunique qualquer dano, desgaste, alteração, perda de ajuste, falha de funcionamento ou condição que comprometa a proteção oferecida pelo EPI. Isso inclui trincas, rasgos, deformações, componentes soltos, elásticos danificados, perda de vedação, visor comprometido, filtros saturados ou qualquer outro sinal de que o equipamento não está mais adequado ao risco.\"},{\"t\":\"Comunicação\",\"f\":\"5\",\"d\":\"Informe imediatamente à liderança ou ao responsável peleo setor RH local, qualquer alteração que torne o EPI impróprio para uso.\"},{\"t\":\"Substituição\",\"f\":\"10\",\"d\":\"Após identificar uma irregularidade, não utilize o EPI danificado, não faça adaptações e não continue a atividade sem uma proteção adequada ao risco.\"},{\"t\":\"Registro\",\"f\":\"14\",\"d\":\"A substituição é registrada na ficha, com data e motivo, do mesmo modo que a entrega inicial. Esse histórico permite acompanhar a durabilidade real de cada modelo e antecipar as próximas trocas.\"}],\"guiado\":true},\"x\":4,\"y\":28,\"w\":63.5,\"h\":64,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:58%;height:2.7%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Substituição</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:11.2%;width:58%;height:7.1%;z-index:1;--trc-fs:1.46;\"><h2>Quando comunicar e como trocar</h2></div>\n<div class=\"trc-el trc-texto\" id=\"e3\" style=\"left:4.5%;top:19.5%;width:63%;height:6.7%;z-index:1;\"><p>A norma organiza esse fluxo em quatro etapas, alternando responsabilidade entre você e a empresa. Conhecê-lo evita o uso prolongado de equipamento que já deixou de proteger.</p></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:28%;width:63.5%;height:64%;z-index:1;--trc-fs:1.15;\"><div class=\"trb trb-passos trb-guiado\" data-bloco=\"passos\" data-guiado=\"1\" data-apos=\"1\"><ol class=\"trb-passos-lista\"><li class=\"trb-passo\" data-gi=\"0\" data-gf=\"1\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">1</span><span class=\"trb-passo-corpo\"><b>Identificação</b><small>Comunique qualquer dano, desgaste, alteração, perda de ajuste, falha de funcionamento ou condição que comprometa a proteção oferecida pelo EPI. Isso inclui trincas, rasgos, deformações, componentes soltos, elásticos danificados, perda de vedação, visor comprometido, filtros saturados ou qualquer outro sinal de que o equipamento não está mais adequado ao risco.</small></span></li><li class=\"trb-passo\" data-gi=\"1\" data-gf=\"5\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">2</span><span class=\"trb-passo-corpo\"><b>Comunicação</b><small>Informe imediatamente à liderança ou ao responsável peleo setor RH local, qualquer alteração que torne o EPI impróprio para uso.</small></span></li><li class=\"trb-passo\" data-gi=\"2\" data-gf=\"10\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">3</span><span class=\"trb-passo-corpo\"><b>Substituição</b><small>Após identificar uma irregularidade, não utilize o EPI danificado, não faça adaptações e não continue a atividade sem uma proteção adequada ao risco.</small></span></li><li class=\"trb-passo\" data-gi=\"3\" data-gf=\"14\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">4</span><span class=\"trb-passo-corpo\"><b>Registro</b><small>A substituição é registrada na ficha, com data e motivo, do mesmo modo que a entrega inicial. Esse histórico permite acompanhar a durabilidade real de cada modelo e antecipar as próximas trocas.</small></span></li></ol></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-02 13:21:37', 'herdar'),
(404, 29, 31, 'Verificação 4', 'zoom', 'cheio', 'solido', '#F2F5F9', '#F3F6FA', 160, NULL, 0, NULL, 0, 'direita', 'auto', 'herdar', 1.00, 'herdar', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":7,\"w\":92,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Verificação de aprendizagem 4<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":13.2,\"w\":92,\"h\":10.5,\"html\":\"<h2>Analise a situação<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":130,\"anim\":\"subir\"},\"id\":\"e3\",\"t\":\"bloco\",\"bloco\":\"quiz\",\"dados\":{\"pergunta\":\"Durante a jornada, a almofada do seu protetor auricular tipo concha apresenta enrijecimento e deixa de vedar. Qual é a conduta prevista?\",\"opcoes\":[{\"t\":\"Comunicar na mesma jornada e aguardar a substituição antes de retornar à área ruidosa\",\"ok\":true},{\"t\":\"Prosseguir até a próxima entrega programada, já que o equipamento ainda está posicionado\",\"ok\":false},{\"t\":\"Improvisar a vedação com espuma ou fita até que a troca ocorra\",\"ok\":false},{\"t\":\"Utilizar o protetor de um colega enquanto a substituição não chega\",\"ok\":false}],\"feedback\":\"A comunicação de equipamento impróprio é dever do trabalhador e a substituição é dever da empresa. Improvisar anula o ensaio e a validade do certificado, e o compartilhamento contraria a condição de uso individual.\",\"varias\":false},\"x\":4,\"y\":23.7,\"w\":92,\"h\":69,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:7%;width:92%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Verificação de aprendizagem 4</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:13.2%;width:92%;height:10.5%;z-index:1;--trc-fs:1.46;\"><h2>Analise a situação</h2></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e3\" style=\"left:4%;top:23.7%;width:92%;height:69%;z-index:1;--trc-fs:1.3;\"><div class=\"trb trb-quiz\" data-bloco=\"quiz\"><div class=\"trb-quiz-topo\"><i class=\"bi bi-patch-question\"></i><span>Pergunta</span></div><p class=\"trb-quiz-pergunta\">Durante a jornada, a almofada do seu protetor auricular tipo concha apresenta enrijecimento e deixa de vedar. Qual é a conduta prevista?</p><div class=\"trb-quiz-ops\"><button type=\"button\" class=\"trb-quiz-op\" data-i=\"0\" data-ok=\"1\"><span class=\"trb-quiz-letra\">A</span><span class=\"trb-quiz-txt\">Comunicar na mesma jornada e aguardar a substituição antes de retornar à área ruidosa</span><i class=\"bi trb-quiz-icone\"></i></button><button type=\"button\" class=\"trb-quiz-op\" data-i=\"1\" data-ok=\"0\"><span class=\"trb-quiz-letra\">B</span><span class=\"trb-quiz-txt\">Prosseguir até a próxima entrega programada, já que o equipamento ainda está posicionado</span><i class=\"bi trb-quiz-icone\"></i></button><button type=\"button\" class=\"trb-quiz-op\" data-i=\"2\" data-ok=\"0\"><span class=\"trb-quiz-letra\">C</span><span class=\"trb-quiz-txt\">Improvisar a vedação com espuma ou fita até que a troca ocorra</span><i class=\"bi trb-quiz-icone\"></i></button><button type=\"button\" class=\"trb-quiz-op\" data-i=\"3\" data-ok=\"0\"><span class=\"trb-quiz-letra\">D</span><span class=\"trb-quiz-txt\">Utilizar o protetor de um colega enquanto a substituição não chega</span><i class=\"bi trb-quiz-icone\"></i></button></div><div class=\"trb-quiz-feedback\"><i class=\"bi bi-info-circle\"></i><span>A comunicação de equipamento impróprio é dever do trabalhador e a substituição é dever da empresa. Improvisar anula o ensaio e a validade do certificado, e o compartilhamento contraria a condição de uso individual.</span></div></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-02 14:46:35', 'quiz'),
(405, 29, 32, 'Encerramento', 'fade', 'esquerda', 'gradiente', '#08243F', '#134E86', 160, NULL, 0, '#FFFFFF', 1, 'direita', 'auto', 'herdar', 1.00, 'full', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":9,\"w\":58,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">Encerramento<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":14,\"w\":63,\"h\":14,\"html\":\"<h2>Segurança depende de atitudes consistentes<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":125,\"anim\":\"subir\",\"bg\":null},\"id\":\"e3\",\"t\":\"bloco\",\"bloco\":\"checklist\",\"dados\":{\"itens\":[{\"t\":\"Use o EPI durante toda a exposição ao risco\",\"f\":\"1\"},{\"t\":\"Utilize o equipamento correto e em condições adequadas\",\"f\":\"3\"},{\"t\":\"Ao identificar um problema, comunique imediatamente\",\"f\":\"5\"}],\"guiado\":true,\"guiaAuto\":true,\"titulo\":\"O que resume o treinamento\"},\"x\":3.5,\"y\":31,\"w\":63.5,\"h\":35.5,\"oculto\":true},{\"z\":1,\"s\":{\"fs\":120,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"alerta\",\"dados\":{\"tipo\":\"ok\",\"titulo\":\"Mensagem Final\",\"texto\":\"Segurança não depende apenas de receber o EPI. Depende de usar, conservar, comunicar e agir corretamente.\"},\"x\":4,\"y\":75,\"w\":63,\"h\":17,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:9%;width:58%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">Encerramento</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:14%;width:63%;height:14%;z-index:1;--trc-fs:1.46;\"><h2>Segurança depende de atitudes consistentes</h2></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e3\" style=\"left:3.5%;top:31%;width:63.5%;height:35.5%;z-index:1;--trc-fs:1.25;\"><div class=\"trb trb-checklist trb-guiado\" data-bloco=\"checklist\" data-guiado=\"1\" data-apos=\"1\" data-gauto=\"1\"><div class=\"trb-titulo\">O que resume o treinamento</div><div class=\"trb-checks\"><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"0\" data-gf=\"1\"><i class=\"bi bi-square\"></i><span>Use o EPI durante toda a exposição ao risco</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"1\" data-gf=\"3\"><i class=\"bi bi-square\"></i><span>Utilize o equipamento correto e em condições adequadas</span></button><button type=\"button\" class=\"trb-check\" data-bloco-ac=\"check\" data-gi=\"2\" data-gf=\"5\"><i class=\"bi bi-square\"></i><span>Ao identificar um problema, comunique imediatamente</span></button></div></div></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:75%;width:63%;height:17%;z-index:1;--trc-fs:1.2;\"><div class=\"trb trb-alerta trb-alerta-ok\" data-bloco=\"alerta\"><i class=\"bi bi-check-circle\"></i><div><b>Mensagem Final</b><p>Segurança não depende apenas de receber o EPI. Depende de usar, conservar, comunicar e agir corretamente.</p></div></div></div>\n</div>', '', '2026-08-31 07:33:43', '2026-09-09 15:13:51', 'nenhuma'),
