(408, 29, 30, 'Penalidades', 'fade', 'esquerda', 'tema', '#FFFFFF', '#F3F6FA', 160, NULL, 0, NULL, 1, 'direita', 'auto', 'herdar', 1.00, 'upper', '<script type=\"application/json\" data-tr-canvas>{\"v\":1,\"els\":[{\"z\":1,\"s\":{\"fs\":124,\"anim\":\"esquerda\"},\"id\":\"e1\",\"t\":\"texto\",\"x\":4,\"y\":9,\"w\":58,\"h\":4,\"html\":\"<div class=\\\"trc-eyebrow\\\">PENALIDADES<\\/div>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":146,\"anim\":\"subir\"},\"id\":\"e2\",\"t\":\"texto\",\"x\":4,\"y\":14.5,\"w\":63,\"h\":14,\"html\":\"<h2>Recusa injustificada do uso do EPI<\\/h2>\",\"oculto\":false},{\"z\":1,\"s\":{\"fs\":120,\"anim\":\"subir\"},\"id\":\"e4\",\"t\":\"bloco\",\"bloco\":\"alerta\",\"dados\":{\"tipo\":\"perigo\",\"titulo\":\"Recusar o uso do EPI pode gerar medidas disciplinares\",\"texto\":\"O EPI deve ser utilizado sempre que houver exposição ao risco, conforme as orientações fornecidas pela organização. A recusa injustificada pode resultar em medidas disciplinares, aplicadas de forma proporcional à situação.\"},\"x\":4,\"y\":25.5,\"w\":63,\"h\":17,\"oculto\":true},{\"t\":\"bloco\",\"bloco\":\"passos\",\"dados\":{\"itens\":[{\"t\":\"A recusa injustificada pode gerar advertência\",\"d\":\"Nesses casos, a organização poderá adotar medidas disciplinares, observando a gravidade da conduta, a reincidência e as circunstâncias do caso.\",\"f\":\"3\"},{\"t\":\"A reincidência pode levar à suspensão\",\"d\":\"A repetição da recusa ou do descumprimento das regras de segurança pode resultar em suspensão disciplinar.\",\"f\":\"5\"},{\"t\":\"Reiteradamente pode ser aplicada a justa causa\",\"d\":\"A recusa reiterada e grave às normas de segurança pode contribuir para a aplicação da justa causa, quando houver fundamento legal.\",\"f\":\"7\"}],\"guiado\":true,\"guiaAuto\":true},\"x\":4.5,\"y\":45,\"w\":62.5,\"h\":47.5,\"s\":{\"fs\":130,\"va\":\"start\"},\"id\":\"e3\",\"z\":2,\"oculto\":true}]}</script>\n<div class=\"trc-palco\">\n<div class=\"trc-el trc-texto trv-anim-esquerda\" id=\"e1\" style=\"left:4%;top:9%;width:58%;height:4%;z-index:1;--trc-fs:1.24;\"><div class=\"trc-eyebrow\">PENALIDADES</div></div>\n<div class=\"trc-el trc-texto trv-anim-subir\" id=\"e2\" style=\"left:4%;top:14.5%;width:63%;height:14%;z-index:1;--trc-fs:1.46;\"><h2>Recusa injustificada do uso do EPI</h2></div>\n<div class=\"trc-el trc-bloco nv-oculto trv-anim-subir\" id=\"e4\" style=\"left:4%;top:25.5%;width:63%;height:17%;z-index:1;--trc-fs:1.2;\"><div class=\"trb trb-alerta trb-alerta-perigo\" data-bloco=\"alerta\"><i class=\"bi bi-shield-exclamation\"></i><div><b>Recusar o uso do EPI pode gerar medidas disciplinares</b><p>O EPI deve ser utilizado sempre que houver exposição ao risco, conforme as orientações fornecidas pela organização. A recusa injustificada pode resultar em medidas disciplinares, aplicadas de forma proporcional à situação.</p></div></div></div>\n<div class=\"trc-el trc-bloco nv-oculto\" id=\"e3\" style=\"left:4.5%;top:45%;width:62.5%;height:47.5%;z-index:2;--trc-fs:1.3;justify-content:flex-start;\"><div class=\"trb trb-passos trb-guiado\" data-bloco=\"passos\" data-guiado=\"1\" data-apos=\"3\" data-gauto=\"1\"><ol class=\"trb-passos-lista\"><li class=\"trb-passo\" data-gi=\"0\" data-gf=\"3\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">1</span><span class=\"trb-passo-corpo\"><b>A recusa injustificada pode gerar advertência</b><small>Nesses casos, a organização poderá adotar medidas disciplinares, observando a gravidade da conduta, a reincidência e as circunstâncias do caso.</small></span></li><li class=\"trb-passo\" data-gi=\"1\" data-gf=\"5\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">2</span><span class=\"trb-passo-corpo\"><b>A reincidência pode levar à suspensão</b><small>A repetição da recusa ou do descumprimento das regras de segurança pode resultar em suspensão disciplinar.</small></span></li><li class=\"trb-passo\" data-gi=\"2\" data-gf=\"7\" role=\"button\" tabindex=\"0\"><span class=\"trb-passo-num\">3</span><span class=\"trb-passo-corpo\"><b>Reiteradamente pode ser aplicada a justa causa</b><small>A recusa reiterada e grave às normas de segurança pode contribuir para a aplicação da justa causa, quando houver fundamento legal.</small></span></li></ol></div></div>\n</div>', '', '2026-09-02 14:28:18', '2026-09-02 15:06:23', 'herdar');

